INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2795', 'spa', 'Mover, poner en movimiento; menear o sacudir (en burla); agitar, conmover; quitar o desplazar de su lugar.', 'Un verbo griego versátil cuyo núcleo es el movimiento. κινέω abarca desde el movimiento físico literal hasta la agitación social figurada. Junto a la cruz, los transeúntes «meneaban la cabeza» (Mt 27:39) en un gesto de escarnio reconocible en todas las culturas. Pablo lo emplea filosóficamente en Atenas: «en él vivimos, nos movemos» (Hch 17:28), fundamentando la existencia humana en el movimiento divino. En Apocalipsis, la palabra adquiere fuerza cósmica: candeleros removidos y montañas desplazados de su lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2796', 'spa', 'Movimiento, agitación o perturbación (especialmente del agua)', 'Este sustantivo denota movimiento o agitación, con usos que van desde el movimiento físico hasta las conmociones políticas y las perturbaciones emocionales. Juan 5:3 describe la agitación de las aguas del estanque de Betesda, aunque este versículo es textualmente incierto en muchos manuscritos. El contexto involucra a enfermos y discapacitados que esperaban la perturbación terapéutica del agua. Jesús trasciende esa esperanza al sanar directamente, sin necesidad de mediación natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2797', 'spa', 'Cis (Κίς), padre del rey Saúl, de la tribu de Benjamín (nombre propio)', 'Nombre propio del padre de Saúl, conservado del texto hebreo. Hechos 13:21 menciona a Saúl como «hijo de Cis» en el sermón que Pablo pronuncia en la sinagoga repasando la historia de Israel. Las transliteraciones en distintos idiomas preservan el nombre (Kis, Kís, Κίς) con variaciones mínimas. Este detalle genealógico identifica de qué Saúl se habla y establece una conexión sutil entre el apóstol Pablo —también llamado Saulo— y el primer rey de Israel, ambos de la tribu de Benjamín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2798', 'spa', 'Rama — rama o ramaje de un arbol; se usa tanto del follaje literal como de la metafora paulina del olivo para referirse a Israel y los gentiles. El su', 'Rama — rama o ramaje de un arbol; se usa tanto del follaje literal como de la metafora paulina del olivo para referirse a Israel y los gentiles. El sustantivo κλάδος (klados) designa una rama o ramaje de arbol. Jesus lo emplea en la parabola de la semilla de mostaza, donde las aves anidan en las ramas de la planta ya crecida (Mt 13:32; Mc 4:32), y en la senal de la higuera, donde las ramas tiernas anuncian el verano (Mt 24:32; Mc 13:28). Las multitudes cortaron ramas para tenderlas ante Jesus en la entrada triunfal (Mt 21:8). Pablo desarrolla el termino teologicamente en Romanos 11:16-21, donde las ramas naturales (Israel) son desgajadas y las ramas de olivo silvestre (los gentiles) son injertadas, una metafora de continuidad del pacto y advertencia contra la presuncion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2799', 'spa', 'Llorar, lamentar — derramar lagrimas por dolor, duelo, tristeza o profunda angustia espiritual', 'Llorar, lamentar — derramar lagrimas por dolor, duelo, tristeza o profunda angustia espiritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2801', 'spa', 'Fragmento o pedazo partido, especialmente las sobras de pan recogidas tras una alimentación milagrosa.', 'Se refiere a un fragmento o pedazo partido, derivado del verbo κλάω (''partir''). En todas sus apariciones en el Nuevo Testamento, κλάσμα designa las sobras de pan recogidas después de las alimentaciones milagrosas de Jesús a las multitudes. Las doce canastas (Mt 14:20, Mr 6:43, Jn 6:12-13) y las siete canastas (Mt 15:37, Mr 8:8) de fragmentos se convirtieron en símbolos poderosos de la abundancia divina que supera toda necesidad humana. Estos pedazos tangibles y concretos subrayan que la provisión de Dios es material y real, no meramente espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2802', 'spa', 'Cauda (también Clauda), pequeña isla cercana a Creta (nombre de lugar)', 'Nombre de una pequeña isla cerca de Creta, mencionada en Hechos 27:16 durante el tormentoso viaje de Pablo hacia Roma. La tradición manuscrita varía entre Cauda y Clauda. El refugio temporal que ofreció la isla permitió a la tripulación asegurar el bote auxiliar y reforzar el casco del navío antes de que la tormenta los arrastrara hacia la Sirte. Este detalle geográfico realza tanto la credibilidad narrativa como el dramatismo del relato lucano, revelando la providencia divina en medio del peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2803', 'spa', 'Claudia, mujer cristiana saludada en 2 Timoteo (nombre propio)', 'Nombre propio de una mujer cristiana mencionada en los saludos finales de la segunda carta de Pablo a Timoteo. En 2 Timoteo 4:21, Claudia aparece entre quienes envían saludos a Timoteo, probablemente como parte de la iglesia en Roma. Su nombre es latino, de la gens Claudia, lo cual sugiere origen romano o alguna vinculación con esa familia. Esta breve mención nos recuerda a los muchos creyentes fieles cuyas historias permanecen mayormente desconocidas, pero cuya comunión sostuvo el ministerio apostólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2804', 'spa', 'Claudio; nombre personal romano llevado tanto por el emperador como por un tribuno militar', 'Un nombre de familia romano (nomen) frecuente, portado por varios individuos en la era neotestamentaria. Se refiere principalmente al emperador Claudio (reinó del 41 al 54 d.C.), durante cuyo gobierno ocurrió una hambruna (Hechos 11:28) y quien expulsó a los judíos de Roma (Hechos 18:2). Hechos 23:26 nos presenta a otro Claudio: Claudio Lisias, el tribuno romano (comandante militar) en Jerusalén que rescató a Pablo de una turba y luego lo trasladó a Cesarea. El nombre refleja la omnipresente influencia romana en la Judea del siglo primero y en el conjunto del imperio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2805', 'spa', 'Llanto, lamento; lloro fuerte y audible que expresa dolor, angustia o duelo.', 'Denota llanto o lamento: un lloro fuerte y audible provocado por el dolor, la angustia o la desesperación. En los Evangelios, κλαυθμός aparece de manera más característica en la frase repetida de Jesús sobre las «tinieblas de afuera» donde habrá «llanto y crujir de dientes» (Mt 8:12; 13:42, 50; 22:13; 24:51; 25:30; Lc 13:28). Esta fórmula recurrente carga al término de un peso escatológico sobrecogedor. También aparece en Mateo 2:18 citando el oráculo de Jeremías sobre Raquel que llora por sus hijos, un pasaje de duelo profundo e inconsolable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2806', 'spa', 'Partir (el pan): el acto físico de romper un pan con las manos, especialmente en comidas comunitarias y sacramentales.', 'Partir (el pan): el acto físico de romper un pan con las manos, especialmente en comidas comunitarias y sacramentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2807', 'spa', 'κλείς — llave; instrumento para cerrar y abrir, usado metafóricamente para la autoridad divina y el acceso.', 'Κλείς es la palabra griega común para llave, el instrumento que cierra y abre una puerta. Sin embargo, en el Nuevo Testamento cada aparición es figurada: las ''llaves del reino'' confiadas a Pedro (Matt 16:19), la ''llave del conocimiento'' acaparada por los doctores de la ley (Luke 11:52), y las llaves de la Muerte y del Hades en poder del Cristo resucitado (Rev 1:18). La imagen es notablemente coherente: una llave representa autoridad delegada sobre un ámbito. El español ''llave'' traduce uniformemente este sentido, confirmando que la metáfora de acceso con autoridad es el único sentido operante en el NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2808', 'spa', 'Cerrar, clausurar, echar llave: de puertas, portones y, en sentido figurado, de autoridad celestial y acceso. El verbo κλείω cubre todo el espectro de', 'Cerrar, clausurar, echar llave: de puertas, portones y, en sentido figurado, de autoridad celestial y acceso. El verbo κλείω cubre todo el espectro de cerrar en el Nuevo Testamento, desde el cierre físico de una puerta hasta la prohibición autoritativa de acceso cósmico. Jesús instruye a sus seguidores a ''cerrar la puerta'' al orar en secreto (Mt 6:6), y la parábola de las diez vírgenes gira en torno al momento aterrador en que ''la puerta fue cerrada'' (Mt 25:10). Pero κλείω también opera en un registro superior: los fariseos ''cierran el reino de los cielos'' contra la gente (Mt 23:13), Cristo tiene la llave de David y ''cierra de modo que nadie abre'' (Ap 3:7), y Elías ''cerró el cielo'' para que no lloviese (Lc 4:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2809', 'spa', 'Robos, bienes robados o actos de hurto', 'Este sustantivo designa objetos robados o actos de hurto, derivado del verbo «robar». Apocalipsis 9:21 incluye los robos entre los pecados de los cuales la humanidad azotada por las plagas se niega a arrepentirse, junto con los homicidios, las hechicerías y la inmoralidad sexual. Las traducciones convergen en el concepto de hurto o robo. Este catálogo de pecados sin arrepentimiento subraya la obstinada rebeldía de la humanidad incluso bajo el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2810', 'spa', 'Cleofas (Κλεοπᾶς), uno de los dos discípulos en el camino a Emaús (nombre propio)', 'Nombre propio de uno de los dos discípulos que Jesús encontró en el camino a Emaús tras su resurrección. Lucas 24:18 identifica a Cleofas como quien responde a la pregunta de Jesús acerca de lo que venían conversando. Las transliteraciones conservan la forma griega (Kleopas, Kleopâs, Cléopas, Κλεοπᾶς). Su acompañante permanece sin nombre. Cleofas se convierte en testigo de una de las apariciones más conmovedoras del Resucitado, en la que Jesús despliega las Escrituras antes de revelarse en el partir del pan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2811', 'spa', 'Crédito, honor, gloria o buena reputación merecida por acciones dignas', 'Este sustantivo designa la buena fama, el honor o la gloria que se obtiene mediante obras dignas. En 1 Pedro 2:20, el apóstol pregunta retóricamente qué mérito o gloria hay en soportar castigo por haber obrado mal, contrastándolo con la alabanza que proviene de sufrir injustamente. El punto de Pedro es que solo el sufrimiento inmerecido, soportado con paciencia siguiendo el ejemplo de Cristo, obtiene la aprobación divina y la verdadera gloria ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2812', 'spa', 'Ladrón; quien toma la propiedad ajena de manera furtiva, a diferencia del salteador que usa violencia. Κλέπτης describe a alguien que roba encubiertam', 'Ladrón; quien toma la propiedad ajena de manera furtiva, a diferencia del salteador que usa violencia. Κλέπτης describe a alguien que roba encubiertamente, en contraste con λῃστής, el bandido o salteador que toma por la fuerza. Jesús advierte contra acumular tesoros donde los ladrones fuerzan la entrada y roban (Mt 6:19-20) y llama ladrón al falso pastor que evita la puerta (Jn 10:1, 10). La palabra adquiere vívida fuerza escatológica cuando el regreso del Señor se compara con un ladrón que llega a una hora inesperada (Mt 24:43; 1 Ts 5:2; Ap 3:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2813', 'spa', 'Robar, tomar ilegalmente; usado del hurto prohibido por el Decálogo y de la sustracción clandestina como el robo de tumbas.', 'Robar, tomar ilegalmente; usado del hurto prohibido por el Decálogo y de la sustracción clandestina como el robo de tumbas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2814', 'spa', 'Pámpano, sarmiento; rama de vid, usado en la alegoría de Jesús sobre la vid verdadera.', 'Designa una rama o brote, especialmente el que crece de una vid. Las cuatro apariciones neotestamentarias provienen de la extensa alegoría de la vid y los pámpanos en Juan 15, donde Jesús declara: ''Yo soy la vid, vosotros los pámpanos''. El griego κλῆμα denota específicamente un sarmiento o zarcillo de vid, no una rama de árbol — el español ''pámpano'' (brote verde de vid) captura esta precisión vitícola con exactitud. La imagen subraya la dependencia orgánica total: un pámpano cortado se seca y es echado al fuego (Jn 15:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2815', 'spa', 'Clemente, colaborador de Pablo mencionado en Filipenses (nombre propio)', 'Nombre propio de un colaborador cristiano a quien Pablo elogia en Filipenses 4:3, junto con otros compañeros de labor cuyos nombres están escritos en el libro de la vida. Las transliteraciones conservan el nombre latino (Κλήμεντος). La tradición antigua a veces lo identificó con Clemente de Roma, aunque esta conexión es incierta. La afirmación de Pablo sitúa a Clemente entre los fieles colaboradores del evangelio cuyo reconocimiento definitivo es escatológico, inscrito en la eternidad por la mano de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2816', 'spa', 'Heredar, recibir como posesión: obtener una porción asignada, ya sea una herencia literal o una bendición divina prometida. Κληρονομέω significa hered', 'Heredar, recibir como posesión: obtener una porción asignada, ya sea una herencia literal o una bendición divina prometida. Κληρονομέω significa heredar o entrar en posesión de una porción asignada, derivado de κλῆρος (''suerte, asignación'') y νόμος (''ley, costumbre''). Sus 18 apariciones en el Nuevo Testamento llevan las ricas resonancias tanto del derecho sucesorio grecorromano como de la teología veterotestamentaria de la tierra prometida como don asignado por Dios a su pueblo. En los Evangelios sinópticos, el joven rico pregunta ''¿qué debo hacer para heredar la vida eterna?'' (Mt 19:29; Mc 10:17; Lc 10:25; 18:18). Las Bienaventuranzas prometen que los mansos ''heredarán la tierra'' (Mt 5:5). La gran escena del juicio en Mateo 25:34 lo usa como clímax: ''Venid, benditos de mi Padre, heredad el reino preparado para vosotros.'' Pablo extiende el concepto teológicamente: los herederos de Abraham heredan la promesa no por la ley sino por la fe (Gá 4:30; 5:21; 1 Co 6:9-10; 15:50). Apocalipsis 21:7 corona el motivo: ''El que venza heredará estas cosas.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2817', 'spa', 'Herencia: la porción recibida de un ancestro, ya sea propiedad material o una parte espiritual divinamente prometida.', 'Herencia: la porción recibida de un ancestro, ya sea propiedad material o una parte espiritual divinamente prometida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2818', 'spa', 'Heredero; persona que recibe una herencia, ya sea por derecho legal o por promesa divina. En el griego clásico, la palabra podía designar tanto al her', 'Heredero; persona que recibe una herencia, ya sea por derecho legal o por promesa divina. En el griego clásico, la palabra podía designar tanto al heredero presunto como al que ya posee la herencia. El Nuevo Testamento emplea ambos sentidos: la parábola de los labradores malvados presenta al hijo como el heredero legítimo a quien los labradores asesinan (Mt 21:38; Mc 12:7), mientras que Pablo y el autor de Hebreos aplican el término teológicamente a los creyentes que son herederos de Dios por la fe (Ro 4:13-14; Gá 3:29; Tit 3:7), e incluso a Cristo mismo como heredero de todas las cosas (Heb 1:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2819', 'spa', 'Suerte echada para tomar decisiones; por extensión, porción asignada, herencia o parte correspondiente. Originalmente el objeto físico que se lanzaba ', 'Suerte echada para tomar decisiones; por extensión, porción asignada, herencia o parte correspondiente. Originalmente el objeto físico que se lanzaba para determinar resultados al azar, κλῆρος adquirió profundos matices teológicos en el Nuevo Testamento. En la cruz, los soldados echaron suertes sobre las vestiduras de Jesús (Mt 27:35; Jn 19:24), cumpliendo el Salmo 22:18. Pero Pablo habla de ''la herencia (κλῆρος) entre los santificados'' (Hch 26:18), y Colosenses 1:12 da gracias al Padre que capacitó a los creyentes ''para participar de la herencia de los santos en luz.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2820', 'spa', 'Fuimos hechos herederos, obtuvimos una herencia o nos fue asignada una porción', 'Este verbo en aoristo pasivo combina las ideas de echar suertes, recibir una herencia y ser designado para una porción. Efesios 1:11 declara que los creyentes ''fuimos hechos herederos'' o ''obtuvimos una herencia'' en Cristo conforme al propósito predeterminado de Dios. El término fusiona la soberanía divina (la designación de Dios) con el don gratuito (la herencia recibida), subrayando que nuestra porción en el reino de Cristo no proviene del azar ni del mérito, sino de la voluntad eterna del Padre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2821', 'spa', 'Llamamiento, vocacion — la convocatoria divina a la salvacion, el servicio y la esperanza que acompana la invitacion de Dios. El sustantivo κλῆσις (kl', 'Llamamiento, vocacion — la convocatoria divina a la salvacion, el servicio y la esperanza que acompana la invitacion de Dios. El sustantivo κλῆσις (klesis) se refiere al llamamiento eficaz de Dios, la convocatoria mediante la cual atrae a las personas a una relacion, a la salvacion y a un proposito. Pablo insiste en que los dones y el llamamiento de Dios son irrevocables (Rom 11:29) e insta a los creyentes a vivir de manera digna de su vocacion (Ef 4:1; 2 Tes 1:11). En 1 Corintios 1:26 senala que no muchos sabios ni poderosos recibieron este llamamiento, subrayando su caracter de gracia. El termino aparece tambien en el sentido de la condicion de vida al momento de la conversion: ''cada uno permanezca en el llamamiento en que fue llamado'' (1 Cor 7:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2822', 'spa', 'Llamado, invitado — convocado divinamente a la salvacion, el servicio o el banquete mesianico. El adjetivo κλητός (kletos) describe a aquellos a quien', 'Llamado, invitado — convocado divinamente a la salvacion, el servicio o el banquete mesianico. El adjetivo κλητός (kletos) describe a aquellos a quienes Dios ha convocado, ya sea a la salvacion, al servicio apostolico o al banquete escatologico. Jesus advierte que ''muchos son llamados, pero pocos escogidos'' (Mt 22:14), distinguiendo la invitacion amplia de la seleccion final. Pablo se presenta como ''apostol llamado'' (Rom 1:1; 1 Cor 1:1) y se dirige a los creyentes como ''santos llamados'' (Rom 1:7; 1 Cor 1:2) y ''llamados conforme a su proposito'' (Rom 8:28). En Apocalipsis, quienes siguen al Cordero son ''llamados, elegidos y fieles'' (Ap 17:14). El termino tiene un peso teologico como marca de la iniciativa divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2824', 'spa', 'región, distrito; área geográfica o territorio definido por límites climáticos o políticos', 'Originalmente relacionada con la «inclinación» de la superficie terrestre en distintas latitudes (de ahí «clima»), esta palabra pasó a designar regiones o distritos geográficos. Pablo la emplea tres veces para describir los amplios territorios donde ejerció su ministerio. En Romanos 15:23 declara que ya no tiene lugar en «estas regiones» del Mediterráneo oriental, donde había fundado iglesias. En 2 Corintios 11:10 y Gálatas 1:21 la usa para referirse a las regiones de Acaya y de Siria-Cilicia respectivamente. El término subraya el alcance geográfico de la estrategia misionera paulina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2825', 'spa', 'Cama, lecho o camilla; mueble para dormir, reclinarse o transportar enfermos.', 'Se refiere a una cama, lecho o camilla: un mueble doméstico usado para dormir, descansar, reclinarse a la mesa o transportar a los enfermos. En los Evangelios, κλίνη aparece de forma prominente en los relatos de sanación donde Jesús dice al paralítico «levántate, toma tu cama y anda» (Mt 9:2, 6; Mr 2:4, 9, 11-12), convirtiendo la cama misma en un accesorio dramático de la historia de restauración. También aparece para la cama donde yace un niño enfermo (Mr 7:30) y en el contexto de pureza ritual con el lavado de lechos (Mr 7:4). El español distingue entre «cama» y «camilla», reflejando el espectro de κλίνη desde el lecho propio hasta la estera portátil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2826', 'spa', 'camilla, lecho pequeño; cama portátil o modesta para transportar enfermos', 'Forma diminutiva que significa «cama pequeña» o «camilla», usada para describir las camas portátiles de la gente humilde o las empleadas para trasladar enfermos. A diferencia de un mueble elaborado, se trataba de simples esteras o parihuelas fáciles de cargar. Lucas la emplea en relatos de sanación: el paralítico cuyos amigos lo bajaron por el techo (Lucas 5:19, 24) y los enfermos colocados en las calles con la esperanza de que la sombra de Pedro los alcanzara (Hechos 5:15). El vocablo resalta tanto la humildad de los sanados como la realidad física de su restauración: podían cargar aquello que antes los había cargado a ellos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2827', 'spa', 'Inclinar, reclinar o acostar; del declinar de la luz del día; de poner en fuga a ejércitos.', 'Construido sobre la raíz que significa ''hacer que algo se incline'', κλίνω abarca un rango sorprendente en el Nuevo Testamento. Jesús dice que el Hijo del Hombre no tiene dónde recostar su cabeza (Mt 8:20; Lc 9:58), y en la cruz inclina su cabeza y entrega el espíritu (Jn 19:30). El mismo verbo describe cómo la luz del día ''declina'' hacia el atardecer (Lc 9:12; 24:29). En Hebreos 11:34 adquiere un giro militar: los héroes de la fe ''hicieron huir'' a ejércitos extranjeros, donde el sentido marcial resulta vívido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2828', 'spa', 'Grupos de personas reclinadas para comer; comensales organizados en secciones', 'Este sustantivo originalmente significaba cabaña o lecho para reclinarse, pero llegó a designar grupos de personas organizadas para comer. En Lucas 9:14, Jesús instruye a los discípulos a sentar a la multitud ''en grupos'' de cincuenta para el milagro de la multiplicación. Esta disposición ordenada facilitaba tanto la distribución del alimento como el conteo de los presentes, transformando lo que pudo ser un caos en una comida comunitaria organizada con resonancias del banquete mesiánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2831', 'spa', 'Ser zarandeado por las olas, azotado por el oleaje o lanzado a la confusión', 'Este verbo en voz pasiva significa ser azotado por el mar embravecido o zarandeado por las olas, con extensión metafórica al sentido de ser perturbado o lanzado a la confusión. En Efesios 4:14, Pablo lo emplea metafóricamente: los creyentes no deben ser ''sacudidos'' por todo viento de doctrina. La imagen náutica de Pablo advierte contra la inestabilidad doctrinal, contrastándola con la madurez arraigada en la verdad que se alcanza al crecer hacia Cristo mediante la verdad proclamada con amor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2832', 'spa', 'Clopas, esposo de una de las Marías presentes en la crucifixión (nombre propio)', 'Nombre propio del hombre identificado en Juan 19:25 como esposo de María, quien estuvo al pie de la cruz de Jesús. El nombre arameo (Κλωπᾶς) es distinto del Cleofás del camino a Emaús, aunque a veces se confunden. Según una tradición antigua, Clopas era hermano de José, lo que haría de su esposa la tía de Jesús. Esta breve referencia preserva la memoria de testigos fieles que permanecieron junto a la cruz en la hora más oscura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2833', 'spa', 'Tener comezón, sentir picazón en los oídos, ansiar constante novedad y estímulo', 'Este verbo significa sentir picazón o rascarse, empleado metafóricamente en 2 Timoteo 4:3 para describir a quienes tienen ''comezón de oír'', es decir, que buscan maestros que les digan lo que desean escuchar en lugar de la sana doctrina. La expresión ''teniendo comezón'' conserva la imagen de la picazón. Esta vívida metáfora retrata la inquieta búsqueda de enseñanzas novedosas o halagadoras que satisfacen la curiosidad sin exigir verdadera transformación interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2834', 'spa', 'Cnido, ciudad costera en el suroeste de Asia Menor (nombre de lugar)', 'Nombre de una ciudad y península en la costa suroeste de Asia Menor, mencionada en Hechos 27:7 como punto en el viaje de Pablo hacia Roma. Las transliteraciones conservan el griego (Κνίδον). El barco tuvo dificultades para llegar a Cnido debido a vientos contrarios, antes de virar al sur hacia Creta. Este marcador geográfico contribuye al detallado relato náutico de Lucas y evidencia los desafíos de la navegación antigua en el Mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2836', 'spa', 'Cavidad corporal: el vientre materno como organo de concepcion y nacimiento, o el estomago/abdomen como organo de digestion y apetito.', 'Cavidad corporal: el vientre materno como organo de concepcion y nacimiento, o el estomago/abdomen como organo de digestion y apetito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2837', 'spa', 'Dormirse; usado como eufemismo para la muerte (especialmente de creyentes), o literalmente del sueño físico. En el Nuevo Testamento, κοιμάω lleva una ', 'Dormirse; usado como eufemismo para la muerte (especialmente de creyentes), o literalmente del sueño físico. En el Nuevo Testamento, κοιμάω lleva una doble vida notable. En su uso teológico más cargado, funciona como un eufemismo delicado para la muerte, retratando al difunto como alguien que simplemente duerme, en espera de la resurrección. Jesús mismo introduce este lenguaje al decir de Lázaro: «Nuestro amigo se ha dormido» (Juan 11:11), y los discípulos lo malinterpretan literalmente. Pablo fundamenta toda una teología de la resurrección sobre esta metáfora: los que «durmieron» en Cristo serán resucitados (1 Co 15:6, 18, 20, 51; 1 Ts 4:13-15). El sentido literal del sueño físico aparece con menor frecuencia, pero proporciona la base de la metáfora, como cuando los guardias de la tumba afirman que los discípulos vinieron mientras ellos dormían (Mt 28:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2838', 'spa', 'Descanso, sueño o el acto de acostarse a dormir', 'Este sustantivo designa el acto de acostarse a dormir o el estado de reposo. Juan 11:13 lo emplea cuando Jesús habla del ''descanso'' (sueño) de Lázaro, aunque los discípulos malinterpretaron sus palabras, creyendo que se refería al sueño natural y no a la muerte. Este eufemismo para la muerte, frecuente en ambos testamentos, subraya tanto la paz del fallecimiento del creyente como la certeza del despertar de la resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2839', 'spa', 'Común — compartido por todos, o ritualmente impuro/profano; los dos sentidos giran en torno a la inclusión comunitaria frente a la exclusión sagrada. ', 'Común — compartido por todos, o ritualmente impuro/profano; los dos sentidos giran en torno a la inclusión comunitaria frente a la exclusión sagrada. κοινός presenta dos perfiles semánticamente distintos en el Nuevo Testamento, casi opuestos en valencia emocional. En una dirección significa ''compartido, comunal'': la fe común de Tito 1:4, la salvación común de Judas 1:3, y los bienes compartidos de la iglesia de Jerusalén (Hch 2:44; 4:32). En la otra dirección, moldeado por la ley de pureza judía, significa ''ritualmente contaminado, profano'': manos sin lavar según la tradición (Mc 7:2, 5), alimentos declarados impuros (Hch 10:14, 28; 11:8; Ro 14:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2840', 'spa', 'Contaminar o hacer ritualmente impuro; declarar profano o llamar común lo que Dios ha purificado. κοινόω entra en el Nuevo Testamento en el punto álgi', 'Contaminar o hacer ritualmente impuro; declarar profano o llamar común lo que Dios ha purificado. κοινόω entra en el Nuevo Testamento en el punto álgido de la ley de pureza. En la enseñanza de Jesús (Mt 15; Mc 7), es lo que sale de la boca — pensamientos malvados, homicidio, adulterio — lo que ''contamina'' a la persona, no las manos sin lavar ni los alimentos prohibidos. La palabra significa literalmente ''hacer común,'' despojar algo de su estatus santo o puro y reducirlo a lo profano. La visión de Pedro en la azotea (Hch 10:15; 11:9) hace explícita toda la fuerza de esta tensión: ''Lo que Dios ha purificado, no lo llames común.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2841', 'spa', 'Compartir, participar, contribuir; tener comunión o participación con otro en algo.', 'κοινωνέω expresa el acto de compartir, participar o tener comunión con alguien en algo. Abarca tanto la contribución generosa de recursos materiales — «contribuyendo a las necesidades de los santos» (Ro 12:13) — como una participación espiritual más profunda, ya sea en el sufrimiento, en la colaboración con el evangelio (Fil 4:15) o incluso en los pecados ajenos (1 Ti 5:22). El español ''compartir'' y el alemán ''teilhaben'' captan ambas facetas de dar una parte y tener parte, que es exactamente el rango que este verbo griego cubre en sus ocho usos neotestamentarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2842', 'spa', 'Comunión, compañerismo, participación — participación en un vínculo común, ya sea unión espiritual o generosidad material. Abarca la profunda particip', 'Comunión, compañerismo, participación — participación en un vínculo común, ya sea unión espiritual o generosidad material. Abarca la profunda participación mutua que define la comunidad cristiana. En su centro teológico se encuentra la comunión del cuerpo y la sangre de Cristo (1 Co 10:16), donde Pablo usa κοινωνία dos veces para describir la participación compartida de los creyentes en la copa y el pan eucarísticos. Lucas la nombra como uno de los cuatro pilares de la iglesia primitiva de Jerusalén, junto con la enseñanza de los apóstoles, el partimiento del pan y la oración (Hch 2:42). La palabra se extiende desde la comunión vertical con Dios y su Hijo (1 Jn 1:3, 6-7) hasta la expresión material y horizontal de ese vínculo: Pablo llama a la colecta macedónica para los pobres de Jerusalén una κοινωνία (Ro 15:26; 2 Co 8:4; 9:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2843', 'spa', 'Dispuesto a compartir, generoso con los bienes propios', 'Pablo emplea este término en su instrucción a los ricos en 1 Timoteo 6:18, exhortándolos a ser generosos y estar dispuestos a compartir sus bienes materiales. La palabra transmite el sentido de comunión o participación aplicado a las posesiones: no se trata de mera caridad, sino de una disposición a incluir a otros en lo que uno posee. La raíz griega se relaciona con κοινωνία (comunión, participación), lo que sugiere que el verdadero compartir genera comunidad en lugar de simple asistencia unilateral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2844', 'spa', 'Partícipe, socio o compañero; alguien que participa de una realidad común o comparte en una empresa o relación conjunta. Describe a quien está unido a', 'Partícipe, socio o compañero; alguien que participa de una realidad común o comparte en una empresa o relación conjunta. Describe a quien está unido a otros mediante una participación compartida, ya sea en una realidad espiritual, un emprendimiento comercial o una causa común. Pablo advierte a los corintios que comer sacrificios ofrecidos a ídolos los convierte en ''partícipes'' con los demonios (1 Co 10:18-20), mientras Pedro se llama a sí mismo ''participante'' en la gloria (1 Pe 5:1) y los creyentes llegan a ser ''partícipes'' de la naturaleza divina (2 Pe 1:4). En su sentido relacional, Santiago y Juan son ''compañeros'' de pesca con Simón (Lc 5:10), Pablo elogia a Tito como su ''compañero'' de ministerio (2 Co 8:23), y Filemón es el querido ''compañero'' de Pablo en la fe (Flm 1:17). El español distingue bien ambos sentidos: ''participante/partícipes'' para realidades espirituales compartidas y ''compañero/compañeros'' para relaciones de asociación personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2845', 'spa', 'Lecho, cama; lugar para dormir o para las relaciones íntimas, tanto el lecho conyugal como las uniones ilícitas.', 'Denota primariamente una cama o lugar de descanso, pero en el NT se extiende desde el lecho literal donde los niños duermen (Lc 11:7) hasta el lecho conyugal como figura de la unión sexual (Ro 9:10; Heb 13:4) e incluso hasta el exceso sexual o el desenfreno (Ro 13:13). El abanico que va desde el español ''cama'' hasta la expresión ''en lechos de inmoralidad'' refleja fielmente esta amplitud semántica. La flexibilidad del término entre el descanso inocente y la intimidad le confiere una fuerza particular en la exhortación moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2846', 'spa', 'dormitorio real, aposento privado para dormir', 'Este término designa el espacio íntimo y privado de un dormitorio o aposento. En Hechos 12:20, Blasto ocupa el cargo de «camarero del rey», es decir, el responsable del dormitorio real, un puesto de enorme confianza y acceso directo al monarca en las cortes antiguas. En el uso clásico, la palabra podía también referirse a una cámara funeraria o sepulcro, pero en el Nuevo Testamento claramente designa las habitaciones privadas del palacio. El término subraya la intimidad del espacio reservado al descanso del soberano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2847', 'spa', 'κόκκινος — escarlata, rojo carmesí; color de lana teñida, vestiduras reales y telas lujosas.', 'Κόκκινος es un adjetivo que significa ''escarlata'' o ''carmesí'', derivado de κόκκος, el insecto quermes del cual se extraía un tinte rojo intenso en la antigüedad. En el Nuevo Testamento aparece en contextos cargados de peso simbólico: el manto escarlata puesto sobre Jesús durante su burla (Matt 27:28), la lana escarlata usada en el rito de purificación del tabernáculo (Heb 9:19), y la mujer vestida de escarlata junto con la bestia escarlata de las visiones apocalípticas de Apocalipsis (Rev 17:3-4; 18:12, 16). Es un color asociado en el mundo antiguo con la realeza, la riqueza y la sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2848', 'spa', 'Grano o semilla; el pequeño núcleo de una planta, usado literal y figuradamente de los inicios diminutos de la fe.', 'En cada aparición neotestamentaria, κόκκος se refiere a una semilla o grano pequeño, recordado sobre todo por la semilla de mostaza en las parábolas del reino (Mt 13:31; Mr 4:31; Lc 13:19). La imagen gira en torno al contraste entre la insignificancia de la semilla y la enorme planta que produce. Jesús extiende la metáfora a la fe misma: una fe del tamaño de un grano de mostaza puede arrancar un árbol de raíz (Lc 17:6) o mover una montaña (Mt 17:20). El término fundamenta algunos de los dichos más queridos de los Evangelios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2850', 'spa', 'adulación, discurso insincero destinado a manipular', 'Pablo niega enfáticamente haber recurrido a la adulación en su ministerio entre los tesalonicenses (1 Tesalonicenses 2:5), distinguiendo así la predicación apostólica genuina de la retórica manipuladora. La literatura griega clásica analiza extensamente la adulación como un vicio: un discurso servil que busca el provecho personal en lugar de la verdad. La palabra no transmite simplemente elogio, sino la intención engañosa que se oculta tras palabras falsas. Se trata de un hablar calculado para agradar al oyente con fines egoístas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2852', 'spa', 'Golpear con el puño, abofetear; dar puñetazos tanto en agresión física como en tormento figurado.', 'Describe la acción específica de golpear con el puño cerrado, una forma de violencia más brutal y degradante que una simple bofetada. Aparece en los relatos de la Pasión, donde los guardias golpean a Jesús tras su juicio (Mt 26:67; Mc 14:65), y Pablo lo emplea para sus propias penalidades apostólicas (1Co 4:11). De modo particularmente memorable, Pablo describe su «aguijón en la carne» como un mensajero de Satanás enviado a «abofetearlo» (2Co 12:7), extendiendo la imagen física al ámbito espiritual. Pedro pregunta qué mérito hay en soportar golpes cuando se ha pecado (1Pe 2:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2853', 'spa', 'Pegar, unir, adherirse; juntarse a una persona, aferrarse con devoción, unirse en matrimonio o pegarse físicamente. Construido sobre el sustantivo gri', 'Pegar, unir, adherirse; juntarse a una persona, aferrarse con devoción, unirse en matrimonio o pegarse físicamente. Construido sobre el sustantivo griego κόλλα (''pegamento''), este verbo porta la imagen central de cosas unidas entre sí. En el Nuevo Testamento va mucho más allá del sentido literal de taller. Un hijo pródigo ''se juntó'' con un ciudadano de un país lejano (Lc 15:15), Pablo ordena a los creyentes ''adherirse'' a lo bueno (Ro 12:9), y Jesús cita Génesis para declarar que el hombre ''se unirá'' a su mujer (Mt 19:5). Incluso el polvo puede κολλάομαι a las sandalias (Lc 10:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2854', 'spa', 'colirio, ungüento medicinal para los ojos', 'En Apocalipsis 3:18, Cristo aconseja a la iglesia de Laodicea que adquiera colirio para poder ver verdaderamente, una metáfora impactante dado que Laodicea era célebre por su escuela médica y sus tratamientos oftalmológicos. La forma diminutiva griega designa un pequeño rollo o pastilla de compuesto medicinal, con forma de panecillo. Los colirios antiguos eran productos valiosos, elaborados con diversos minerales y hierbas. La ironía resulta punzante: una iglesia rodeada de medicina ocular necesita visión espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2855', 'spa', 'cambista; persona que cambia moneda y convierte denominaciones grandes en más pequeñas', 'En los recintos del templo, los cambistas prestaban un servicio necesario: convertir las diversas monedas extranjeras en la plata tiria requerida para el impuesto del templo y fraccionar monedas grandes en denominaciones menores aptas para comprar animales de sacrificio. Sin embargo, esta función legítima se había corrompido: los cambistas cobraban tasas abusivas y habían convertido el Atrio de los Gentiles en un mercado en vez de una casa de oración. La acción contundente de Jesús al volcar sus mesas (Mateo 21:12, Marcos 11:15, Juan 2:15) desafió tanto la explotación económica como la usurpación del espacio de adoración gentil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2856', 'spa', 'Acortar, abreviar; reducir o recortar la duración de un período de tiempo.', 'Significa acortar, truncar o abreviar. Originalmente se usaba para la mutilación o el recorte físico, pero en el NT aparece exclusivamente en el contexto escatológico de Dios acortando los días de tribulación por causa de los elegidos (Mt 24:22; Mc 13:20). Cada pasaje emplea el verbo dos veces: una para declarar que los días «fueron acortados» y otra para afirmar que el Señor «los acortó», subrayando la intervención soberana divina. El sentido clásico de mutilación física está completamente ausente; el uso neotestamentario es enteramente temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2857', 'spa', 'Colosas, ciudad de Frigia a la que Pablo dirigió su epístola', 'Esta ciudad frigia del valle del Lico fue destinataria de una de las epístolas de Pablo escritas desde la prisión. Aunque en tiempos antiguos fue prominente, para el siglo I Colosas había quedado eclipsada por las vecinas Laodicea y Hierápolis. La iglesia local fue aparentemente fundada por Epafras y no por el ministerio directo de Pablo. El nombre de la ciudad aparece únicamente en el encabezamiento de la carta (Colosenses 1:2). La evidencia arqueológica sigue siendo limitada, ya que el sitio nunca fue excavado de forma extensiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2858', 'spa', 'Colosense; residente o nativo de Colosas (variante ortográfica: Κολασσαεύς/Κολοσσαεύς)', 'Adjetivo o sustantivo que identifica a alguien procedente de Colosas, la ciudad frigia a la que Pablo dirigió su epístola a los Colosenses. Las tradiciones manuscritas muestran variación ortográfica entre Κολασσαεύς y Κολοσσαεύς, lo cual refleja incertidumbre sobre la forma exacta del nombre de la ciudad. El término aparece en el título y la suscripción de la epístola en ciertos testimonios textuales. Colosas se encontraba en el valle del río Lico, junto a Laodicea y Hierápolis, formando un triángulo de comunidades cristianas primitivas que enfrentaban los desafíos sincretistas abordados en la carta de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2859', 'spa', 'Seno, regazo, pecho; por extension una bahia o ensenada — todo pliegue curvo que envuelve o cobija', 'Enraizado en la imagen de un pliegue o curva, κόλπος en su uso primario neotestamentario designa el seno, regazo o pecho como lugar de cercanía íntima y abrazo protector. El «seno de Abraham» (Lucas 16:22-23) se convirtió en una poderosa imagen judía del lugar de descanso de los justos tras la muerte, un refugio cálido después del camino de la vida. Juan se recuesta sobre el seno de Jesús en la Última Cena (Juan 13:23), y el Hijo mismo existe «en el seno del Padre» (Juan 1:18), expresando la intimidad más profunda posible. En Hechos 27:39 la misma metáfora raíz — un pliegue curvo — se traslada a la geografía: una bahía o ensenada en la costa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2860', 'spa', 'nadar, lanzarse al agua y desplazarse en ella', 'Lucas narra el naufragio de Pablo con preciso detalle náutico, incluyendo la orden del centurión de que «los que supieran nadar» se arrojaran primero al agua y alcanzaran tierra firme (Hechos 27:43). El verbo aparece en el griego clásico para designar la acción de nadar, zambullirse o lanzarse al agua. En el dramático contexto del naufragio frente a Malta, la capacidad de nadar se convierte en cuestión de supervivencia. El rango semántico del verbo abarca tanto la natación experta como el desesperado chapoteo en el agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2861', 'spa', 'Estanque, piscina; depósito público de agua o cisterna alimentada por una fuente.', 'Designa un estanque o piscina, un depósito construido o natural para almacenar agua. Todas las apariciones neotestamentarias se refieren a estanques específicos de Jerusalén con nombre propio: el estanque de Betesda (Jn 5:2, 4, 7) y el estanque de Siloé (Jn 9:7). No eran elementos decorativos, sino instalaciones hidráulicas vitales en una ciudad árida. Las excavaciones arqueológicas han confirmado ambos como grandes depósitos tallados en piedra. El español «estanque» y «piscina» reflejan fielmente el sentido de reservorio público para baño y recolección de agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2862', 'spa', 'colonia, asentamiento romano con estatus legal especial', 'Lucas identifica a Filipos como ''ciudad principal del distrito de Macedonia y colonia romana'' (Hechos 16:12). El término latino ''colonia'' designaba ciudades con privilegios especiales, frecuentemente pobladas por soldados romanos retirados que conservaban sus derechos de ciudadanía. Estas colonias reproducían la vida cívica romana en contextos provinciales. Filipos recibió este estatus tras la batalla del 42 a.C. Esta designación explica el marcado carácter romano de la ciudad y la preocupación de los magistrados por la ciudadanía romana en el relato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2864', 'spa', 'cabellera, cabello largo; gloria de la mujer (1 Co 11:15)', 'El complejo argumento de Pablo sobre las cubiertas de la cabeza en el culto apela al ''cabello largo'' como gloria natural y cobertura de la mujer (1 Corintios 11:15). El término griego se refiere específicamente al cabello de la cabeza cuando se lleva largo, una práctica asociada con la belleza femenina tanto en la cultura griega como en la judía. El uso clásico incluye referencias a peinados elaborados y el contraste entre el cabello largo y el rapado. Pablo recurre tanto a la naturaleza como a la convención cultural en su razonamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2865', 'spa', 'Recibir lo que corresponde (una recompensa, promesa o retribución); también traer o llevar algo a una persona o lugar. Enraizada en la idea de cuidar ', 'Recibir lo que corresponde (una recompensa, promesa o retribución); también traer o llevar algo a una persona o lugar. Enraizada en la idea de cuidar o proveer, κομίζω en el Nuevo Testamento aparece mayormente en voz media con el significado de recibir de vuelta u obtener algo que se debe: un salario, una promesa, una retribución por las obras hechas en el cuerpo (2 Co 5:10). Traducciones al español como ''obteniendo'' y ''habría-recibido'' captan bien este matiz transaccional. En una notable excepción (Lc 7:37), aparece la voz activa: la mujer pecadora ''habiendo traído'' un frasco de alabastro con perfume. El cambio de recibir a transportar físicamente revela el sentido clásico más antiguo de la palabra, que pervive bajo el uso dominante del NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2866', 'spa', 'mejor, en sentido comparativo de mejoría o recuperación', 'Cuando el oficial del rey pregunta a qué hora su hijo comenzó a recuperarse (Juan 4:52), los siervos responden: ''ayer a la hora séptima le dejó la fiebre''. El adverbio en su respuesta significa literalmente ''mejoró'' o ''se puso mejor''. La raíz clásica se relaciona con la elegancia y el refinamiento. Aquí funciona como un simple comparativo: la condición del hijo mejoró, la fiebre cedió. La ironía dramática reside en que esta mejoría coincidió exactamente con la palabra sanadora de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2868', 'spa', 'Polvo levantado del suelo; nube de partículas finas alzadas por el movimiento o el viento.', 'Se refiere específicamente al polvo que ha sido levantado o removido, no al polvo asentado sino a una nube de partículas finas en el aire. En los Evangelios y Hechos, sacudirse el polvo de los pies es un acto simbólico de separación y juicio cuando un pueblo rechaza el mensaje (Mt 10:14; Lc 9:5; 10:11). Pablo y Bernabé realizan este gesto en Antioquía de Pisidia (Hch 13:51). En Hch 22:23, una multitud enfurecida arroja polvo al aire como señal de indignación. La etimología griega (de κόνις «polvo» y ὄρνυμι «agitar») subraya la cualidad dinámica e inquieta de las partículas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2869', 'spa', 'cesar, amainar; detenerse o calmarse, especialmente referido al viento o las tormentas', 'Este verbo describe el cese o la disminución de fenómenos naturales, en particular el viento y las tormentas. Los Evangelios lo emplean exclusivamente para la calma de tempestades cuando Jesús ordena al viento y las olas. En Mateo 14:32, el viento cesó cuando Jesús y Pedro subieron a la barca. Marcos 4:39 y 6:51 describen igualmente el cese del viento: la primera vez tras la reprensión de Jesús «¡Calla, enmudece!» y la segunda al entrar él en la barca mientras caminaba sobre el agua. La cesación inmediata demuestra la autoridad de Jesús sobre las fuerzas caóticas de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2870', 'spa', 'lamentación, duelo público y sonoro por los muertos', 'Lucas describe la escena en el entierro de Esteban: ''Hombres piadosos sepultaron a Esteban e hicieron gran lamentación sobre él'' (Hechos 8:2). El término denota el duelo ritualizado y en voz alta, propio de los funerales mediterráneos antiguos: no un dolor silencioso, sino una expresión pública y vocal de la pérdida. El uso clásico lo vincula con golpearse el pecho y los lamentos fúnebres formales. La palabra aparece en contextos de muerte y duelo comunitario, expresando tanto el dolor personal como el ritual social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2871', 'spa', 'matanza, derrota violenta en batalla', 'Hebreos 7:1 alude a Abraham ''cuando regresaba de la derrota de los reyes'', la narrativa de Génesis 14 donde Abraham venció a la coalición que había capturado a Lot. El término griego enfatiza el abatimiento violento de los enemigos en batalla, una derrota decisiva más que una matanza sacrificial. El uso clásico incluye el sentido más amplio de cortar o golpear, pero en contextos bélicos significa derrota contundente. La palabra subraya la victoria militar que precedió a la bendición de Melquisedec.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2872', 'spa', 'Trabajar arduamente o fatigarse; esfuerzo extenuante en el trabajo o ministerio, y el agotamiento resultante del esfuerzo.', 'Trabajar arduamente o fatigarse; esfuerzo extenuante en el trabajo o ministerio, y el agotamiento resultante del esfuerzo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2873', 'spa', 'Trabajo, esfuerzo o labor ardua; también molestia o fastidio causado a alguien, frecuentemente en la expresión «causar molestia». κόπος capta el lado ', 'Trabajo, esfuerzo o labor ardua; también molestia o fastidio causado a alguien, frecuentemente en la expresión «causar molestia». κόπος capta el lado agotador y sudoroso del esfuerzo. En su sentido primario en el NT, denota trabajo extenuante y labor productiva, ya sea en la agricultura, el ministerio o el servicio apostólico. Pablo lo usa repetidamente para validar su propio trabajo incansable por el evangelio (1 Co 15:58; 2 Co 6:5; 10:15; 11:23, 27; 1 Ts 1:3). Un sentido secundario aparece en la expresión κόπους παρέχειν, «causar molestia», donde el enfoque pasa del esfuerzo productivo a la carga no deseada. Jesús usa esta frase para defender a la mujer que lo ungió (Mt 26:10; Mr 14:6), y la viuda persistente agota al juez injusto por la molestia que le causa (Lc 18:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2875', 'spa', 'Cortar, golpear; en voz media, llorar o lamentarse golpeándose el pecho en duelo.', 'El verbo κόπτω tiene una larga historia en griego que se remonta a Homero, donde significaba golpear o herir. En el Nuevo Testamento se divide claramente en dos usos: un sentido físico de cortar ramas (Mt 21:8, Mr 11:8) y un ritual de duelo en el que las personas se golpeaban el pecho en señal de aflicción. El sentido de lamento — empleado en voz media — refleja una conocida costumbre del antiguo Cercano Oriente de golpearse a uno mismo como expresión externa de dolor. Jesús lo evoca en Mt 24:30 cuando todas las tribus de la tierra «se lamentarán», y Ap 1:7 hace eco de la misma lamentación escatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2876', 'spa', 'cuervo, ave carroñera negra', 'Jesús señala a los cuervos como ejemplos de la provisión divina: «Considerad los cuervos, que ni siembran ni siegan, y Dios los alimenta» (Lucas 12:24). Estas aves, consideradas ceremonialmente impuras en la ley levítica, se convierten en lecciones vivas de confianza. El griego clásico incluye a los cuervos en expresiones proverbiales y presagios meteorológicos. La elección de cuervos —en lugar de gorriones, como en el paralelo de Mateo— puede reflejar su reputación como carroñeros dependientes de la providencia y no de la agricultura humana. El cuidado de Dios alcanza incluso a las aves impuras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2877', 'spa', 'Muchacha, niña; término diminutivo para una niña o adolescente.', 'κοράσιον es un diminutivo de κόρη (''muchacha, doncella'') y se refiere a una niña o jovencita. En los Evangelios aparece exclusivamente en dos contextos narrativos: la resurrección de la hija de Jairo, donde Jesús se dirige a la niña muerta con ternura (Mt 9:24-25; Mr 5:41-42), y la historia de la hija de Herodías que danzó ante Herodes (Mt 14:11; Mr 6:22, 28). El alemán ''Mädchen'' es a su vez un diminutivo (de ''Magd''), lo que lo convierte en un equivalente especialmente acertado que conserva el registro afectivo e informal del original griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2879', 'spa', 'Coré, israelita rebelde contra Moisés (Números 16)', 'Judas advierte que los falsos maestros «perecieron en la rebelión de Coré» (Judas 11), aludiendo al relato de Números 16 sobre la insurrección levítica. Coré encabezó una revuelta contra la autoridad de Moisés y Aarón, alegando que todo Israel era igualmente santo. El juicio de Dios fue contundente: la tierra se abrió y tragó a los rebeldes. Judas ve un patrón: desafiar el liderazgo divinamente establecido conduce a la destrucción. El nombre mismo se convierte en sinónimo de rebelión presuntuosa contra el orden de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2882', 'spa', 'Κόρινθος — Corinto, la prospera ciudad comercial griega en el istmo, sede de una importante iglesia paulina', 'Κόρινθος es el nombre propio de la antigua ciudad griega de Corinto, estratégicamente situada en el estrecho istmo que une el Peloponeso con la Grecia continental. Célebre en la antigüedad por su comercio, riqueza y permisividad moral, se convirtió en sede de una de las fundaciones eclesiales más significativas y turbulentas del apóstol Pablo. Pablo llegó allí desde Atenas (Hechos 18:1), permaneció dieciocho meses, y posteriormente escribió al menos dos epístolas mayores a la congregación corintia (1 Corintios 1:2; 2 Corintios 1:1). El nombre se conserva con mínima adaptación fonética en las distintas lenguas: español Corinto, francés Corinthe, alemán Korinth.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2883', 'spa', 'Cornelio; centurión romano en Cesarea, primer converso gentil mencionado por nombre en Hechos.', 'Nombre propio de un centurión romano estacionado en Cesarea, descrito como devoto, temeroso de Dios, generoso en limosnas y constante en la oración (Hch 10:1-2). Cornelio ocupa un lugar fundamental en la narrativa de Hechos como el primer gentil explícitamente nombrado que recibe el Espíritu Santo y es bautizado, un acontecimiento que transformó profundamente la comprensión de la iglesia primitiva sobre el alcance universal del evangelio. Su historia en Hechos 10-11 tiende un puente entre la misión judía y la gentil. El nombre es de origen latino (Cornelius), conservado con mínima adaptación en diversas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2884', 'spa', 'cor, medida hebrea de áridos (aprox. 10-12 bushels o 370 litros)', 'En la parábola del administrador astuto, uno de los deudores debe «cien medidas de trigo» (Lucas 16:7). El término es un préstamo hebreo para una gran medida de áridos, el cor, equivalente a unos 10-12 bushels o aproximadamente 370 litros. Esto representa una deuda agrícola considerable: la producción de varias hectáreas. La reducción de veinte medidas por parte del administrador sería significativa, aunque menos dramática que la rebaja del cincuenta por ciento en la deuda de aceite. El comercio antiguo requería estas medidas estandarizadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2885', 'spa', 'Adornar, embellecer o decorar; también poner en orden, arreglar o preparar. De la misma raíz que κόσμος (''orden, mundo''), κοσμέω encierra un doble sig', 'Adornar, embellecer o decorar; también poner en orden, arreglar o preparar. De la misma raíz que κόσμος (''orden, mundo''), κοσμέω encierra un doble significado que refleja cómo los griegos veían la belleza como inseparable del buen orden. Siete de sus diez apariciones en el NT describen el acto de adornar: ya sean las tumbas de los profetas (Mt 23:29), el templo con hermosas piedras (Lc 21:5), o el adorno sereno del carácter de una mujer piadosa (1 Pe 3:5). Sin embargo, en tres pasajes significa simplemente poner en orden: las vírgenes insensatas ''arreglaron'' sus lámparas (Mt 25:7), y una casa barrida queda ''puesta en orden'' (Mt 12:44, Lc 11:25). El alemán ''schmücken'' capta el sentido ornamental, mientras que el español ''arreglaron'' apunta al significado práctico y preparatorio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2888', 'spa', 'gobernadores del mundo, potestades cósmicas de las tinieblas', 'La descripción paulina de la guerra espiritual identifica a «los gobernadores de las tinieblas de este mundo» como adversarios (Efesios 6:12). El término compuesto combina «cosmos» (mundo/orden) con «kratōr» (gobernante/poder), sugiriendo seres que ejercen dominio sobre sistemas caídos. En el uso clásico, este título se aplicaba a emperadores y deidades planetarias. Pablo degrada a estos presuntos gobernantes cósmicos a meros enemigos de la iglesia, ya derrotados por Cristo. La batalla espiritual involucra poderes que pretenden una autoridad suprema que realmente no poseen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2889', 'spa', 'Mundo, creación ordenada, sociedad humana; también adorno: la tierra habitada o el sistema de valores humanos; raramente, decoración.', 'Κόσμος porta una carga teológica inmensa en el Nuevo Testamento. Enraizado en la idea de «orden» y «disposición», se convirtió en el término estándar para el universo creado, la tierra habitada y —especialmente en los escritos joánicos— el orden humano caído que se halla en tensión con el reino de Dios. «De tal manera amó Dios al κόσμος» (Jn 3:16) abraza a toda la humanidad rebelde con compasión divina. Sin embargo, κόσμος también designa lo hostil a Dios: «el κόσμος no le conoció» (Jn 1:10). En una sola aparición notable (1 P 3:3), la palabra regresa a su raíz etimológica y significa adorno o decoración exterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2890', 'spa', 'Cuarto, hermano cristiano en Corinto (Romanos 16:23)', 'Pablo concluye su carta a Roma con saludos de varios creyentes corintios, incluyendo a «Cuarto, el hermano» (Romanos 16:23). El nombre latino significa «cuarto», posiblemente indicando orden de nacimiento o condición de esclavo. La sencilla designación «el hermano» podría sugerir que era bien conocido en la iglesia de Roma, o simplemente enfatiza su condición en la fe. Más allá de esta breve mención, nada cierto se sabe de Cuarto. Representa a los muchos creyentes fieles que aparecen una sola vez en las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2891', 'spa', 'koum, imperativo arameo ''levántate'' (transliterado)', 'Marcos preserva las palabras arameas originales que Jesús pronunció a la hija muerta de Jairo: ''Talitha koum'', es decir, ''Niña, a ti te digo, levántate'' (Marcos 5:41). El evangelista transliteró el imperativo arameo antes de ofrecer la traducción al griego. Esta conservación del habla original de Jesús aporta vivacidad y autenticidad al relato del milagro. Es uno de varios pasajes donde Marcos retiene el arameo de Jesús, preservando los sonidos mismos presentes en el momento del prodigio. La sencillez del mandato —simplemente ''levántate''— contrasta con la magnitud de resucitar a una niña.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2892', 'spa', 'guardia; destacamento militar romano asignado para vigilar un lugar', 'Préstamo del latín (custodia) que designa un destacamento militar de guardia. Esta palabra aparece únicamente en el relato de la pasión según Mateo, en relación con la guardia apostada en la tumba de Jesús. Pilato concede a los sumos sacerdotes y fariseos «una guardia» para asegurar el sepulcro (27:65-66), sellando la piedra y apostando soldados para impedir que los discípulos robaran el cuerpo. Al producirse la resurrección, algunos de la guardia informan a los sumos sacerdotes de lo sucedido (28:11), lo que desencadena el soborno para propagar la versión de que los discípulos robaron el cuerpo mientras dormían. Irónicamente, la guardia destinada a impedir el testimonio de la resurrección se convierte en testigo involuntario de ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2893', 'spa', 'aligeraron (la nave), arrojaron la carga por la borda', 'El detallado relato lucano del naufragio describe las medidas desesperadas de la tripulación para salvar la embarcación. En Hechos 27:38, después de comer, ''aligeraron la nave echando el trigo al mar''. El verbo significa aligerar, reducir peso. Habiendo ya lanzado al mar la carga y los aparejos, ahora sacrifican su provisión de alimento: el trigo formaba probablemente parte del cargamento de grano que iba de Egipto a Roma. Este último intento de aligerar la nave revela cuán desesperada se había vuelto la situación, pues ya no quedaba nada prescindible a bordo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2894', 'spa', 'κόφινος — canasta rigida de mimbre, asociada especificamente al uso judio y a los milagros de alimentacion', 'Κόφινος designa un tipo particular de canasta — un recipiente rígido de mimbre trenzado que las fuentes antiguas asocian específicamente con la vida cotidiana judía. Juvenal se burlaba de los judíos como gente cuyo «mobiliario es un κόφινος y un manojo de heno». En el Nuevo Testamento, las seis apariciones se refieren a las doce canastas de sobras recogidas tras la alimentación de los cinco mil (Mateo 14:20; 16:9; Marcos 6:43; 8:19; Lucas 9:17; Juan 6:13). Los evangelistas distinguen cuidadosamente κόφινος de σπυρίς (la canasta mayor de la alimentación de los cuatro mil), y el propio Jesús subraya esta distinción en Mateo 16:9-10.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2895', 'spa', 'Camilla, catre, lecho — una estera portátil para dormir o cama sencilla, prominente en los relatos de sanación. El sustantivo κράβαττος (krabattos) de', 'Camilla, catre, lecho — una estera portátil para dormir o cama sencilla, prominente en los relatos de sanación. El sustantivo κράβαττος (krabattos) designa la estera o camilla de una persona pobre: una cama simple y liviana que podía enrollarse y cargarse. Aparece de forma destacada en los relatos de sanación donde la persona restaurada recibe la orden de levantarse y cargar la misma camilla que la había confinado. El paralítico que fue bajado por el techo en Capernaúm toma su κράβαττος por la palabra de Jesús (Mc 2:4-12), y el inválido de Betesda hace lo mismo tras treinta y ocho años (Jn 5:8-11). En Hechos, los enfermos son colocados en camillas en las calles esperando que la sombra de Pedro cayera sobre ellos (Hch 5:15; 9:33). La palabra es coloquial, posiblemente de origen macedonio, y contrasta con la más refinada κλίνη. El español ''camilla/lecho'' y el francés ''grabat'' reflejan su connotación humilde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2896', 'spa', 'Gritar, clamar o dar voces con fuerza, ya sea por angustia, urgencia o proclamación pública.', 'Un vocablo visceral y físico para la expresión vocal fuerte, más cercano a un grito o alarido que al habla ordinaria. Sus raíces clásicas incluyen el graznido de los cuervos y el chillido de las ranas, y esa cualidad cruda e incontrolada persiste en el Nuevo Testamento. Cuando los endemoniados claman ante Jesús (Mt 8:29) o Pedro grita mientras se hunde (Mt 14:30), la palabra transmite urgencia angustiosa. Pero también porta fuerza proclamatoria: el ''¡Hosanna!'' de la multitud (Mr 11:9), el grito estratégico de Pablo ante el Sanedrín (Hch 23:6) y el ''¡Santo, santo, santo!'' de Apocalipsis 4:8 emplean este mismo verbo, ahora canalizado hacia la declaración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2897', 'spa', 'resaca, embriaguez; dolor de cabeza por borrachera o los efectos posteriores del exceso en la bebida y la disipación', 'Este sustantivo designa tanto la embriaguez misma como las secuelas físicas del consumo excesivo de alcohol, lo que comúnmente llamamos resaca. Las fuentes clásicas lo emplean para referirse a las francachelas, la intoxicación y el dolor de cabeza que les sigue. En Lucas 21:34, Jesús advierte a sus discípulos que cuiden sus corazones para que no se entorpezcan con κραιπάλῃ, la disipación o embriaguez. El contexto lo empareja con μέθῃ (borrachera) y las ansiedades de la vida, sugiriendo un estilo de vida de excesos que embota la vigilancia espiritual. Las traducciones varían entre ''disipación'', ''glotonería'' e ''intoxicación'', reflejando el rango semántico desde el acto hasta sus consecuencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2898', 'spa', 'Cráneo, calavera; la parte ósea superior de la cabeza, usada como topónimo del Gólgota/Calvario.', 'Designa el cráneo o calavera, la estructura ósea que recubre la parte superior de la cabeza. En los cuatro relatos evangélicos aparece como parte del topónimo «el lugar de la Calavera» (Κρανίον), traduciendo el arameo Gólgota y vertido al latín como Calvaria, de donde proviene «Calvario». Sigue siendo objeto de debate si el sitio recibió su nombre por una formación rocosa con apariencia de cráneo o por su asociación con las ejecuciones. El español «cráneo» y «calavera» reflejan directamente el término anatómico griego κρανίον.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2899', 'spa', 'Borde, orla o fleco de un vestido; específicamente las franjas rituales (tzitzit) usadas por los judíos observantes.', 'Designa el borde o la franja de una vestidura, y en el Nuevo Testamento se refiere específicamente a las borlas rituales (en hebreo, tzitzit) que los varones judíos llevaban en las esquinas de sus mantos conforme a Números 15:38-39. La mujer con hemorragia toca el κράσπεδον del manto de Jesús buscando sanidad (Mt 9:20; Lc 8:44), y las multitudes procuran tocar siquiera este borde para ser sanadas (Mt 14:36; Mr 6:56). Jesús reprende a los fariseos por alargar sus flecos para aparentar mayor piedad (Mt 23:5). Los términos «flecos» y «borde» en español captan tanto el detalle textil como el límite de la prenda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2900', 'spa', 'poderoso, fuerte (dicho de la mano de Dios)', 'Pedro exhorta a los creyentes a ''humillarse bajo la poderosa mano de Dios'' (1 Pedro 5:6). Este adjetivo, una forma poética que enfatiza fuerza y poder, aparece frecuentemente en la Septuaginta describiendo la ''mano poderosa'' de Dios en sus actos de liberación y juicio. La expresión evoca el Éxodo y las intervenciones poderosas de Dios en la historia. Pedro aplica esta imagen tradicional a las circunstancias presentes: el poder de Dios actúa ahora a través del sufrimiento y la humillación, prometiendo una exaltación futura. La ''mano poderosa'' puede tanto salvar como disciplinar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2901', 'spa', 'Fortalecer, robustecerse; ser fortalecido o vigorizado en cuerpo o espíritu.', 'Significa hacer fuerte o llegar a ser fortalecido, empleado tanto en sentido físico como espiritual. Lucas lo usa dos veces al describir el desarrollo infantil de Jesús: el niño «se fortalecía» (Lc 1:80; 2:40), evocando una maduración vigorosa e integral. Pablo lo aplica al fortalecimiento espiritual: como imperativo a los corintios, «sed fuertes» (1 Co 16:13), y como oración para que los creyentes sean «fortalecidos con poder en el hombre interior» (Ef 3:16). La forma reflexiva «fortaleceos» capta la cualidad participativa de este robustecimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2902', 'spa', 'Asir, arrestar, agarrar, retener; abarca desde la aprehension hostil hasta el toque sanador y la firme adhesion a una ensenanza.', 'Asir, arrestar, agarrar, retener; abarca desde la aprehension hostil hasta el toque sanador y la firme adhesion a una ensenanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2903', 'spa', 'Excelentísimo, nobilísimo; título superlativo de honor para dirigirse a funcionarios de alto rango.', 'Superlativo de «fuerte» o «bueno», que en el Nuevo Testamento funciona exclusivamente como título honorífico para funcionarios romanos, equivalente al latín egregius o al tratamiento «Su Excelencia». Lucas se dirige a su destinatario Teófilo como κράτιστε (Lc 1:3), y Pablo emplea el mismo título al hablar ante los gobernadores Félix (Hch 24:3) y Festo (Hch 26:25), así como en la carta de Lisias a Félix (Hch 23:26). El español «excelentísimo» refleja con precisión la fuerza superlativa de este tratamiento cortesano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2904', 'spa', 'Poder, dominio, potencia — fuerza soberana o autoridad suprema, especialmente en atribuciones doxológicas a Dios. κράτος denota poder soberano puro y ', 'Poder, dominio, potencia — fuerza soberana o autoridad suprema, especialmente en atribuciones doxológicas a Dios. κράτος denota poder soberano puro y dominio gobernante, distinguiéndose de δύναμις (capacidad inherente) y ἐξουσία (autoridad delegada) al enfatizar la fuerza absoluta del dominio. Sus 12 apariciones en el NT son abrumadoramente doxológicas — la palabra aparece en fórmulas de alabanza que atribuyen poder eterno a Dios o a Cristo (1 P 4:11; 5:11; Jud 25; Ap 1:6; 5:13; 1 Ti 6:16). Lucas 1:51 lo aplica al brazo poderoso de Dios que dispersa a los soberbios, y Hechos 19:20 describe la palabra del Señor creciendo en κράτος.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2905', 'spa', 'Gritar fuertemente, clamar o vociferar; forma intensificada de κράζω que expresa urgencia o vehemencia vocal.', 'Verbo intensificado que significa gritar fuertemente, clamar o vociferar — más fuerte que el común κράζω. En el Nuevo Testamento, κραυγάζω transmite una expresión vocal enérgica y urgente en contextos variados: la multitud gritando ''¡Crucifícale!'' ante Pilato (Jn 19:6, 15), la multitud de la entrada triunfal clamando ''¡Hosanna!'' (Jn 12:13), y el propio Jesús llamando a Lázaro del sepulcro con gran voz (Jn 11:43). Mateo 12:19 cita la profecía de Isaías de que el Siervo ''no gritará'' (κραυγάσει) en las calles, utilizando la intensidad de esta palabra para resaltar la sorprendente mansedumbre del Mesías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2906', 'spa', 'κραυγή — grito fuerte, clamor o vocerío; exclamacion que expresa urgencia, angustia, gozo o contienda', 'Κραυγή designa un grito vocal fuerte — un clamor, exclamación o vocerío impulsado por una emoción intensa. Sus apariciones neotestamentarias abarcan un amplio espectro emocional: el clamor de medianoche que anuncia la llegada del esposo (Mateo 25:6), la exclamación gozosa de Elisabet al saludo de María (Lucas 1:42), los gritos airados durante el juicio de Pablo ante el Sanedrín (Hechos 23:9), los «ruegos y súplicas con gran clamor y lágrimas» de Jesús en Getsemaní (Hebreos 5:7), y el vicio del clamor iracundo que los creyentes deben desechar (Efesios 4:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2908', 'spa', 'Mejor, superior; comparativo de bueno, que indica lo que sobresale en calidad, valor o mérito moral.', 'Adjetivo comparativo que significa «mejor» o «superior», enraizado en el sentido griego antiguo de «más fuerte» o «más poderoso» (de κρατύς). En el Nuevo Testamento funciona de manera consistente como comparativo de ἀγαθός, evaluando una opción frente a otra. Pablo lo usa para sopesar opciones sobre el matrimonio (1 Co 7:38) y para expresar su deseo de partir y estar con Cristo como algo «mucho mejor» (Fil 1:23). Las cuatro ocurrencias neotestamentarias convergen en un único sentido evaluativo de superioridad cualitativa, más que de fuerza física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2909', 'spa', 'Mejor, superior, más excelente; comparativo que indica mayor valor o mayor fortaleza. Adjetivo comparativo que significa ''mejor'' o ''superior,'' usado c', 'Mejor, superior, más excelente; comparativo que indica mayor valor o mayor fortaleza. Adjetivo comparativo que significa ''mejor'' o ''superior,'' usado cuando una cosa supera a otra en calidad, valor o condición moral. Aunque su raíz clásica significaba ''más fuerte'' o ''más poderoso,'' el uso neotestamentario abrumadoramente lleva el sentido evaluativo de ''más excelente.'' Hebreos lo emplea como una palabra clave virtual: Cristo media un mejor pacto (Heb 7:22), fundado en mejores promesas (Heb 8:6), mediante un mejor sacrificio (Heb 9:23). Pablo también lo usa de forma práctica: es mejor casarse que quemarse de pasión (1 Co 7:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2910', 'spa', 'Colgar, suspender físicamente (especialmente en ejecución); figuradamente, depender de algo.', 'El verbo κρεμάννυμι (con su forma contracta κρεμάω) significa colgar o suspender, y en el Nuevo Testamento aparece en la intersección de dos imágenes vívidas. Físicamente describe la ejecución: Cristo y los criminales fueron colgados en una cruz (Lc 23:39; Hch 5:30; 10:39), y también el peligro corporal, como cuando una víbora se prende de la mano de Pablo en Malta (Hch 28:4). Figuradamente, en uno de los pronunciamientos más memorables de Jesús, toda la Ley y los Profetas ''cuelgan'' de los dos grandes mandamientos (Mt 22:40), una imagen de dependencia tan impactante que pasó al habla cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2911', 'spa', 'barranco escarpado, precipicio; una pendiente abrupta o acantilado que cae a pico', 'Esta palabra describe un barranco empinado, una pendiente abrupta o un acantilado que cae a pico, el tipo de terreno peligroso donde un paso en falso puede resultar en una caída mortal. Los Evangelios Sinópticos la emplean en sus relatos paralelos del exorcismo de los demonios llamados «Legión». Cuando los demonios entran en la piara de cerdos, los animales se precipitan por el barranco escarpado hacia el mar y se ahogan (Mateo 8:32, Marcos 5:13, Lucas 8:33). El detalle geográfico es significativo: la costa oriental del mar de Galilea presenta acantilados pronunciados que descienden hasta el agua, lo que confiere un vívido realismo a esta dramática narración de liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2913', 'spa', 'Crescente, compañero de Pablo (2 Timoteo 4:10)', 'En su última carta, Pablo señala que ''Crescente se ha ido a Galacia'' (2 Timoteo 4:10). El nombre latino significa ''que crece'' o ''que aumenta''. A diferencia de Demas, mencionado en el mismo versículo como alguien que abandonó a Pablo, Crescente aparentemente partió en una misión legítima de ministerio. Algunos manuscritos leen ''Galia'' en lugar de ''Galacia'', lo cual haría de este pasaje una de las referencias más tempranas a la misión cristiana en Europa occidental. Más allá de esta única mención, nada seguro se sabe de Crescente ni de su obra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2914', 'spa', 'Creta; la gran isla mediterránea al sur del mar Egeo, asociada con el viaje de Pablo y la misión de Tito.', 'Nombre propio de la isla de Creta, la mayor del archipiélago griego, situada al sur del mar Egeo. Aparece de forma prominente en el viaje marítimo de Pablo hacia Roma (Hch 27:7, 12-13, 21), donde el barco navega a lo largo de la costa de Creta y la tripulación desatiende fatídicamente el consejo de Pablo de invernar allí. Tito 1:5 revela que Pablo dejó a Tito en Creta para organizar las iglesias y nombrar ancianos en cada ciudad. Se trata de un topónimo bien conocido cuya forma se conserva de manera consistente en las diversas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2915', 'spa', 'de cebada, hecho de grano de cebada', 'En la visión de hambruna y trastorno económico de Apocalipsis, una voz anuncia precios inflados: ''Un litro de trigo por un denario, y tres litros de cebada por un denario'' (Apocalipsis 6:6). La cebada, más barata y menos apreciada que el trigo, servía como alimento de los pobres y como forraje para animales. La forma genitiva aquí indica ''grano de cebada'' o ''producto de cebada''. Los precios sugieren una escasez severa donde incluso la tosca cebada se vuelve costosa. Era una economía de subsistencia: el salario de un día entero por el pan de un día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2917', 'spa', 'Juicio, veredicto, condenacion; tambien un pleito o caso legal presentado ante un tribunal.', 'Juicio, veredicto, condenacion; tambien un pleito o caso legal presentado ante un tribunal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2919', 'spa', 'Juzgar, emitir juicio, condenar; también decidir o determinar; en pasiva, ser juzgado o comparecer en juicio.', 'Κρίνω es el verbo griego fundamental para el juicio, abarcando desde la evaluación hasta el veredicto legal y la decisión personal. La advertencia de Jesús «no juzguéis, para que no seáis juzgados» (Mt 7:1) emplea la voz activa y la pasiva en un solo aliento. Pablo lo aplica al tribunal escatológico (Ro 2:16) y a las disputas congregacionales cotidianas (1 Co 6:2). En Hechos se desliza hacia «decidir, determinar»: Pablo «decidió» pasar de largo por Éfeso (Hch 20:16) y el concilio de Jerusalén «determinó» sus decretos (Hch 16:4). El español juzgar, el francés juger y el alemán richten reflejan este mismo núcleo judicial heredado de la tradición jurídica grecolatina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2920', 'spa', 'Juicio, condenación — el acto de emitir un veredicto, divino o humano, y la sentencia resultante.', 'κρίσις denota el arco completo del proceso judicial: el acto de juzgar, el veredicto emitido y la sentencia ejecutada. A lo largo de 48 ocurrencias neotestamentarias, abarca desde las advertencias de Jesús sobre el ''día del juicio'' que aguarda a Sodoma y Gomorra (Mt 10:15; 11:22, 24) hasta la declaración joánica de que ''el Padre ha dado todo el juicio al Hijo'' (Jn 5:22, 27). Porta tanto peso forense como escatológico: los escribas ''devoran las casas de las viudas y como pretexto hacen largas oraciones — recibirán mayor condenación'' (Mr 12:40). Sin embargo, la palabra también conserva su sentido clásico de ''discernimiento'' en la reprensión de Jesús a los fariseos que descuidan ''la justicia, la misericordia y la fe'' (Mt 23:23), donde κρίσις significa justicia en sentido ético más que escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2922', 'spa', 'tribunal, juzgado; asamblea judicial para resolver disputas legales', 'Aunque esta palabra puede referirse a un criterio o medio de juicio, en el Nuevo Testamento designa específicamente los tribunales o juzgados donde se dirimen disputas. El uso de Pablo es particularmente incisivo: reprocha a los creyentes de Corinto por llevar sus conflictos ante tribunales seculares en lugar de resolverlos dentro de la comunidad cristiana. Si los santos han de juzgar al mundo e incluso a los ángeles (1 Corintios 6:2), ciertamente son competentes para juzgar «asuntos triviales» (6:4) entre ellos. Santiago 2:6 emplea el plural para describir cómo los ricos arrastran a los pobres ante los tribunales, denunciando así la opresión económica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2923', 'spa', 'Juez — aquel que emite decisiones legales, arbitra disputas o ejerce juicio divino. Designa a una persona que dicta sentencias judiciales, ya sea en t', 'Juez — aquel que emite decisiones legales, arbitra disputas o ejerce juicio divino. Designa a una persona que dicta sentencias judiciales, ya sea en tribunales humanos o como título para Dios. En los Evangelios Sinópticos, Jesús advierte sobre ser entregado al juez (Mt 5:25; Lc 12:58), usando el escenario del tribunal como parábola de urgencia escatológica. Hechos lo aplica a los líderes premonárquicos de Israel, los «jueces» que Dios levantó como libertadores (Hch 13:20). Santiago advierte a los ricos que no arrastren a los pobres ante los jueces (Stg 2:6), pero también advierte a los creyentes que no se conviertan en «jueces con malos pensamientos» (Stg 2:4). De manera más notable, Hebreos llama a Dios «el Juez de todos» (12:23) y Santiago declara que hay «un solo Legislador y Juez» (4:12). El español distingue «Juez» con mayúscula para Dios y «juez» con minúscula para los funcionarios humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2924', 'spa', 'que discierne, capaz de juzgar y discernir (referido a la palabra de Dios)', 'Hebreos declara que la palabra de Dios es ''viva y eficaz, más cortante que toda espada de dos filos... y discierne los pensamientos y las intenciones del corazón'' (Hebreos 4:12). El adjetivo significa ''capaz de discernir'' o ''crítico'', con la facultad de juzgar y discriminar. En el uso clásico describía a críticos literarios y eruditos capaces de distinguir calidad y significado. Aplicado a la palabra de Dios, subraya la capacidad de penetrar el autoengaño humano y exponer los verdaderos motivos. La Escritura misma ejerce juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2925', 'spa', 'Llamar a una puerta; golpear una puerta buscando entrada, usado literal y metafóricamente para la oración persistente o la visitación divina.', 'Significa llamar o golpear a una puerta buscando que se abra. En el Nuevo Testamento, κρούω tiene un sentido tanto literal como ricamente metafórico. La enseñanza de Jesús «llamad y se os abrirá» (Mt 7:7-8; Lc 11:9-10) convierte el acto de llamar a la puerta en una imagen vívida de la oración persistente y expectante. En la parábola de la puerta cerrada, los siervos del amo llaman esperando su regreso (Lc 12:36), y en Hechos 12:13-16 Pedro llama a la puerta tras su liberación milagrosa de la prisión, en una escena de sorpresa casi cómica. De manera aún más notable, Apocalipsis 3:20 presenta a Cristo de pie ante la puerta llamando, invirtiendo la metáfora para que sea lo divino quien busca entrar en el corazón humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2926', 'spa', 'lugar oculto, sitio secreto, escondite', 'Jesús enseña que ''nadie enciende una lámpara y la pone en un sótano o debajo de una vasija'' (Lucas 11:33). El ''sótano'' o ''lugar oculto'' representa cualquier sitio escondido de la vista. El punto es que la luz existe para ser vista: ocultarla anula su propósito. El uso clásico incluye criptas, bóvedas y espacios subterráneos de almacenamiento. La metáfora de Jesús critica a quienes esconden la verdad en vez de exhibirla abiertamente. La luz pertenece al candelero, visible para todos los que entran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2927', 'spa', 'Oculto, secreto, escondido — lo que es invisible para los demás pero conocido por Dios. Describe lo que está encubierto a la vista o al conocimiento h', 'Oculto, secreto, escondido — lo que es invisible para los demás pero conocido por Dios. Describe lo que está encubierto a la vista o al conocimiento humano, con una fuerte carga teológica en el NT. Jesús lo usa seis veces en el Sermón del Monte (Mt 6:4-18) para contrastar la piedad ostentosa con los actos hechos «en secreto» ante un Padre que «ve en lo secreto», estableciendo un principio fundacional de la espiritualidad cristiana. Pablo lo aplica a las dimensiones ocultas de la persona: las «cosas secretas» del corazón que Dios expondrá en el juicio (Ro 2:16; 1 Co 4:5; 14:25) y la «persona oculta del corazón» como verdadera belleza (1 P 3:4). Marcos 4:22 y Lucas 8:17 prometen que nada oculto permanecerá sin ser revelado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2928', 'spa', 'Esconder u ocultar; en voz pasiva/media, estar escondido, yacer oculto o esconderse — abarcando tanto el ocultamiento deliberado como los estados de o', 'Esconder u ocultar; en voz pasiva/media, estar escondido, yacer oculto o esconderse — abarcando tanto el ocultamiento deliberado como los estados de ocultamiento. κρύπτω es el verbo griego básico para esconder, y el Nuevo Testamento explota tanto su voz activa como pasiva con rico efecto teológico. Activamente, describe esconder un tesoro en un campo (Mt 13:44), enterrar un talento (Mt 25:18, 25) o una mujer que esconde levadura en la harina (Lc 13:21). En sus formas pasiva y media, habla de verdades ocultas a la percepción humana — cosas «escondidas desde la fundación del mundo» (Mt 13:35), realidades ocultas a los sabios (Mt 11:25; Lc 10:21) y el significado de las palabras de Jesús escondido de los discípulos (Lc 18:34).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2929', 'spa', 'cristalino, claro como el cristal, resplandeciente como cristal', 'La visión de Juan de la Nueva Jerusalén incluye su resplandor: ''teniendo la gloria de Dios, su fulgor era semejante a una piedra preciosísima, como piedra de jaspe, diáfana como el cristal'' (Apocalipsis 21:11). El participio describe la cualidad de ser transparente y brillante como el cristal. Los cristales antiguos, incluido el cuarzo transparente, representaban claridad y pureza perfectas. El verbo transmite el proceso de cristalización: volverse perfectamente claro y luminoso. La ciudad santa posee un brillo sobrenatural que refleja la gloria misma de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2931', 'spa', 'en secreto, secretamente, de manera oculta', 'Pablo describe las ''obras infructuosas de las tinieblas'' en las que los creyentes no deben participar, añadiendo que ''es vergonzoso aun hablar de lo que ellos hacen en secreto'' (Efesios 5:12). El adverbio enfatiza el ocultamiento y la clandestinidad: acciones realizadas fuera de la vista porque no resisten el escrutinio. El uso clásico describe actos secretos, ya sean conspiratorios o simplemente privados. El argumento de Pablo es que las obras de las tinieblas requieren secreto precisamente porque son vergonzosas; el solo hecho de mencionarlas en público resulta deshonroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2932', 'spa', 'Adquirir, procurarse, obtener posesión de algo; usado para comprar bienes, obtener un derecho o ganar dominio sobre algo.', 'Κτάομαι significa procurarse algo para uno mismo, ya sea mediante compra, esfuerzo o autodisciplina. En Mateo 10:9 Jesús prohíbe a los Doce adquirir oro, plata o cobre para el camino, subrayando la dependencia radical de Dios. El verbo abarca tanto la adquisición material (Hch 1:18, donde Judas ''adquirió un campo'' con su paga de sangre) como la disciplina espiritual de dominio propio (1 Ts 4:4, ''ganar control del propio cuerpo''). La voz media griega subraya que quien adquiere actúa en beneficio propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2933', 'spa', 'Posesion, propiedad; bien adquirido y poseido, especialmente hacienda o riqueza material', 'Sustantivo derivado de κτάομαι (''adquirir'') que designa una posesion concreta: algo que se ha obtenido y se retiene como propiedad. En el griego clasico podia referirse a cualquier bien adquirido, desde esclavos hasta herencias, pero en el NT aparece en contextos de riqueza inmobiliaria. El joven rico se fue triste porque tenia muchos κτήματα (Mt 19:22; Mc 10:22), y los primeros creyentes en Jerusalen vendian sus propiedades para repartir el producto entre los necesitados (Hch 2:45; 5:1). El termino subraya la naturaleza tangible y material de estos bienes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2934', 'spa', 'Animal domestico, bestia de carga; criatura poseida para transporte, labor o ganado', 'De la misma raiz que κτάομαι (''adquirir''), κτῆνος significaba originalmente ''propiedad'' en forma de ganado: rebanos y manadas. Para la epoca del NT se habia ampliado para incluir cualquier animal domestico, en particular bestias de montura o transporte. El buen samaritano coloca al herido sobre su propio κτῆνος (Lc 10:34), y a Pablo le proporcionan cabalgaduras (κτήνη) para su traslado seguro ante Felix (Hch 23:24). En 1 Co 15:39 Pablo lo emplea en sentido biologico mas amplio, distinguiendo la carne de los κτήνη de la de humanos, aves y peces.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2935', 'spa', 'dueños, poseedores de propiedades', 'Lucas describe la vida económica compartida de la iglesia primitiva: ''No había entre ellos ningún necesitado, porque todos los que poseían tierras o casas las vendían'' (Hechos 4:34). El término simplemente designa a los poseedores o dueños, aquellos que tenían la titularidad legal de bienes inmuebles. La redistribución voluntaria de la iglesia de Jerusalén involucraba a propietarios reales que vendían sus bienes para sostener a los necesitados. Fue generosidad extraordinaria, no comunismo obligatorio. Los dueños se convirtieron en donadores, creando igualdad económica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2936', 'spa', 'Crear, fundar o dar existencia; como participio sustantivado, el Creador — aquel que origina todas las cosas. Verbo enraizado en la tradición griega d', 'Crear, fundar o dar existencia; como participio sustantivado, el Creador — aquel que origina todas las cosas. Verbo enraizado en la tradición griega de fundar ciudades y colonizar tierras, κτίζω adquiere un enorme peso teológico en el Nuevo Testamento, donde expresa el acto de Dios de traer todas las cosas a la existencia. Pablo lo usa para describir tanto la creación original (Col 1:16) como la nueva creación espiritual de los creyentes (Ef 2:10; 4:24). El participio sustantivado ''el que creó'' se convierte en un título de Dios mismo, como en Romanos 1:25, donde Pablo contrasta la adoración a la criatura con la adoración al Creador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2937', 'spa', 'Creación u orden creado; también una institución u ordenanza humana establecida por autoridad. Enraizado en el verbo κτίζω (crear), este sustantivo ab', 'Creación u orden creado; también una institución u ordenanza humana establecida por autoridad. Enraizado en el verbo κτίζω (crear), este sustantivo abarca desde el acto cósmico de la creación divina hasta sus resultados concretos: toda criatura que Dios ha hecho. Pablo lo invoca para declarar los atributos invisibles de Dios visibles «desde la creación del mundo» (Ro 1:20), mientras que Marcos lo usa para «toda criatura» bajo el cielo (Mr 16:15). En una extensión notable en 1 Pedro 2:13, la misma palabra se aplica a las instituciones humanas, mostrando cómo la mente griega podía ver las estructuras gubernamentales como una especie de ordenamiento con propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2938', 'spa', 'Cosa creada, criatura; todo ser traido a la existencia por un creador, especialmente por Dios', 'Sustantivo derivado de κτίζω (''crear, fundar'') que designa el producto de la creacion. Mientras que en el uso clasico podia significar ''colonia'' o ''fundacion'', el NT lo emplea exclusivamente para los seres creados por Dios. Pablo declara que toda κτίσμα de Dios es buena (1 Ti 4:4), Santiago llama a los creyentes una especie de primicias entre las criaturas de Dios (Stg 1:18), y Apocalipsis contempla a toda κτίσμα en el cielo, la tierra y el mar alabando al Cordero (Ap 5:13). El sentido teologico de ''criatura'' como obra de Dios es constante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2939', 'spa', 'Creador, el que crea y establece todas las cosas', 'Pedro anima a los creyentes que sufren a ''encomendar sus almas al fiel Creador'' (1 Pedro 4:19). El título subraya el papel de Dios como fundador y hacedor de todo lo existente. En el uso clásico incluía a fundadores de ciudades y constructores; la Septuaginta lo aplica a Dios como Creador del universo. El argumento de Pedro es pastoral: aquel que creó puede ser confiado para preservar. Si Dios fundó la creación misma, puede sostener a su pueblo en medio del sufrimiento. La fidelidad del Creador hacia su obra garantiza su cuidado por quienes fueron hechos a su imagen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2940', 'spa', 'astucia, juego de dados, manipulación engañosa', 'Pablo advierte a los creyentes que no permanezcan como niños inmaduros, ''sacudidos por las olas y llevados de aquí para allá por todo viento de enseñanza, por la astucia de los hombres, por las artimañas engañosas'' (Efesios 4:14). La palabra originalmente significaba ''juego de dados'' y luego se extendió al engaño y la manipulación asociados con las apuestas. Los falsos maestros operan como tahúres deshonestos, usando trucos y tácticas engañosas. La metáfora sugiere tanto aleatoriedad (dados) como engaño calculado (dados cargados). La madurez espiritual permite reconocer tales manipulaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2941', 'spa', 'administraciones, gobierno, capacidad de liderazgo y dirección', 'En la lista paulina de dones espirituales, Pablo incluye las ''administraciones'' entre los dones del Espíritu (1 Corintios 12:28). El término significa literalmente ''actos de pilotaje'' o ''timonear'', la habilidad de guiar un barco a su destino. Extendido metafóricamente, describe la capacidad de dar dirección y gobierno a una comunidad. Así como un piloto navega aguas peligrosas, quienes poseen este don guían a la iglesia a través de los desafíos. El liderazgo administrativo, lejos de ser meramente organizativo, es un carisma sobrenatural para conducir al pueblo de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2943', 'spa', 'alrededor, en derredor; por todos lados, en círculo', 'Adverbio que indica rodeo o circundación por todos lados. La visión de Juan en el Apocalipsis emplea esta palabra para describir la disposición en torno al trono de Dios: un arcoíris lo rodea (4:3), veinticuatro tronos con ancianos se sitúan a su alrededor (4:4), y los cuatro seres vivientes están ubicados en derredor del trono, cada uno cubierto de ojos por todas partes (4:8). Este posicionamiento espacial subraya la centralidad del trono divino en el cielo, con todos los seres creados —simbolizados por los veinticuatro ancianos y los cuatro seres vivientes— orientados hacia la presencia divina en adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2944', 'spa', 'Rodear, cercar, formar un circulo alrededor; usado para asedio militar, cerco de multitudes y reunion cosmica', 'Describe la accion de formar un circulo alrededor de algo o alguien: rodear, cercar o asediar. Jesus profetiza que Jerusalen sera rodeada por ejercitos (Lc 21:20), y los lideres judios lo rodean en el templo exigiendole una respuesta clara (Jn 10:24). En Hch 14:20 los discipulos forman un circulo alrededor de Pablo apedreado. Hebreos 11:30 recuerda como los israelitas rodearon Jerico durante siete dias hasta que sus murallas cayeron. Apocalipsis 20:9 representa el asedio final donde fuerzas hostiles rodean el campamento de los santos. La raiz κύκλος (circulo) es visible en cada uso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2945', 'spa', 'Alrededor, en derredor, en círculo; preposición/adverbio que indica orientación espacial circular.', 'Κύκλῳ funciona como preposición y adverbio con el significado de «alrededor», «en derredor» o «en círculo». Deriva de κύκλος (''círculo, anillo'') y transmite la idea espacial de rodear o circundar. Jesús mira «alrededor» a los que están sentados en círculo a su alrededor (Mc 3:34); recorre «los alrededores» de las aldeas enseñando (Mc 6:6); y Pablo describe su predicación del evangelio «en un circuito» desde Jerusalén hasta Ilírico (Ro 15:19). El español «alrededor» y el alemán «ringsumher» enfatizan esa cualidad envolvente y abarcadora de este término espacial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2946', 'spa', 'revolcadero, lodazal donde se revuelcan los cerdos', 'Pedro cita un proverbio sobre los apóstatas: ''El perro vuelve a su propio vómito, y la puerca lavada a revolcarse en el cieno'' (2 Pedro 2:22). El término designa el lugar lodoso donde los cerdos se revuelcan. La imagen es deliberadamente repulsiva: quien experimenta la limpieza pero regresa a la inmundicia es como una cerda bañada que se dirige directamente al lodazal. El proverbio ilustra la tragedia de la apostasía: conocer la verdad pero escoger la contaminación. Es la naturaleza imponiéndose: los cerdos serán siempre cerdos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2947', 'spa', 'rodaba, se revolcaba (en convulsiones demoniacas)', 'Marcos describe la reacción violenta del muchacho endemoniado al ser traído ante Jesús: el espíritu ''inmediatamente lo sacudió con convulsiones, y cayó al suelo revolcándose y echando espuma por la boca'' (Marcos 9:20). El verbo retrata un movimiento de rodar y agitarse violentamente, las convulsiones provocadas por el tormento demoníaco. La misma raíz aparece para describir el revolcarse de los cerdos en el lodo, pero aquí se refiere a sacudidas involuntarias y dolorosas. La escena subraya la crueldad del demonio y la indefensión del muchacho antes de que Jesús intervenga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2948', 'spa', 'Lisiado, mutilado, deforme; que tiene un miembro inutilizado o amputado, especialmente mano o pie', 'Adjetivo que describe una deformidad fisica, en particular la perdida o inutilizacion de un miembro. El griego clasico lo usaba para pies deformes o piernas torcidas, pero el uso neotestamentario se centra en manos y pies mutilados o lisiados. En los relatos de sanacion de Mt 15:30-31, los κυλλοί aparecen junto a ciegos, cojos y mudos como receptores del poder restaurador de Jesus. En las enseñanzas radicales de Mt 18:8 y Mc 9:43, Jesus emplea el termino hiperbolicamente: es mejor entrar en la vida κυλλόν que ser arrojado entero a la Gehena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2949', 'spa', 'Ola o oleaje del mar; se usa literal para el agua embravecida y figuradamente para la inestabilidad moral.', 'Derivado de una raiz que significa ''hincharse'', este sustantivo evoca el movimiento ondulante y encrespado del agua oceanica. En los Evangelios describe las olas aterradoras que anegaron la barca de los discipulos (Mt 8:24; 14:24; Mc 4:37), mientras que en Hch 27:41 capta el oleaje destructor que destrozo el barco de Pablo. Judas 1:13 convierte la imagen en metafora: los falsos maestros son ''fieras olas del mar que espuman su propia verguenza''. Las traducciones multilingues lo traducen consistentemente como ''ola(s)'', confirmando un enfoque semantico concentrado en el agua agitada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2950', 'spa', 'címbalo, instrumento de percusión usado en la música religiosa', 'Pablo declara que el amor es indispensable: sin él, ''vengo a ser como metal que resuena o címbalo que retiñe'' (1 Corintios 13:1). Los címbalos eran instrumentos de percusión utilizados en la adoración, incluido el servicio del templo. El punto no es que los címbalos sean malos, sino que son mero ruido sin contexto ni propósito musical. El habla sin amor es como un címbalo golpeado al azar: estruendoso pero vacío de significado. Pablo posiblemente alude también a los ritos religiosos paganos donde los címbalos acompañaban el frenesí extático. El amor distingue la comunicación genuina del sonido hueco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2951', 'spa', 'comino, semilla aromática usada como especia y condimento', 'Jesús reprende a los escribas y fariseos por sus prioridades distorsionadas: ''Diezmáis la menta, el eneldo y el comino, y descuidáis lo más importante de la ley'' (Mateo 23:23). El comino era una pequeña semilla aromática usada como condimento, económicamente insignificante comparada con los cultivos principales. El meticuloso diezmo de hierbas de huerto por parte de los fariseos demostraba su precisión legal, pero también revelaba sus valores invertidos: se concentraban en lo mínimo mientras ignoraban la justicia y la misericordia. Un proverbio clásico sobre partir semillas de comino describía la tacañería extrema. Jesús no condena su diezmo, sino su descuido de lo verdaderamente importante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2952', 'spa', 'Perrito, perro pequeño domestico; diminutivo cariñoso para un perro de casa, distinto de los perros callejeros.', 'Forma diminutiva de κύων (''perro''), κυνάριον designa especificamente un perro pequeño domestico — una mascota del hogar, no el despreciado carroñero callejero. Esta distincion es teologicamente significativa en el dialogo de la mujer sirofenicia con Jesus (Mt 15:26-27; Mc 7:27-28). Cuando Jesus dice que el pan de los hijos no debe echarse a los κυναρίοις, la mujer convierte brillantemente el diminutivo en su favor: incluso los perritos debajo de la mesa comen las migajas de los hijos. El español ''perritos'' preserva perfectamente el matiz afectivo del diminutivo que hace este dialogo tan memorable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2953', 'spa', 'chipriota, de Chipre; persona originaria de la isla de Chipre', 'Este adjetivo identifica a alguien como oriundo de Chipre, la gran isla mediterránea al sur de Asia Menor. Chipre tenía una importante población judía en el siglo primero, y los creyentes chipriotas desempeñaron papeles destacados en el cristianismo primitivo. Bernabé, compañero misionero de Pablo, era «levita, natural de Chipre» (Hechos 4:36). Tras la persecución en Jerusalén, creyentes chipriotas figuraron entre quienes viajaron a Antioquía y predicaron por primera vez a los griegos (11:20). Hechos 21:16 menciona a Mnasón de Chipre, «discípulo antiguo» que hospedó a Pablo. La conexión chipriota resalta la expansión geográfica y la diversidad étnica de la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2954', 'spa', 'Chipre, la gran isla mediterranea al sur de Asia Menor, importante como base de la mision cristiana primitiva.', 'Chipre (en griego Κύπρος) es la tercera isla mas grande del Mediterraneo, situada justo al sur de la costa de la actual Turquia. Famosa en la antiguedad como fuente de cobre — del latin cyprium proviene la palabra — Chipre adquirio importancia estrategica para la iglesia primitiva. Bernabe era chipriota de nacimiento (Hch 4:36), y la isla sirvio como primera escala en su viaje misionero con Pablo (Hch 13:4). Las cinco referencias neotestamentarias aparecen en Hechos, trazando la expansion del evangelio a traves de esta encrucijada del mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2955', 'spa', 'inclinarse, agacharse; inclinar o doblar el cuerpo hacia abajo', 'Este verbo describe la acción física de inclinarse o agacharse, generalmente para mirar algo en el suelo o para manifestar humildad. Los relatos evangélicos lo emplean en dos contextos significativos. En Juan 8:6, 8, Jesús se inclina para escribir en el suelo cuando le confrontan con la mujer sorprendida en adulterio, un gesto cuyo significado ha suscitado interminables conjeturas. Marcos 1:7 lo usa figuradamente: Juan el Bautista se declara indigno de inclinarse para desatar las correas de las sandalias del Mesías, una tarea tan servil que incluso los esclavos a veces estaban exentos de ella. La postura física comunica una profunda humildad espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2956', 'spa', 'Κυρηναῖος — cirenense; persona oriunda de Cirene, la colonia griega en el norte de Africa (actual Libia)', 'Κυρηναῖος es un gentilicio (adjetivo étnico usado como sustantivo) que significa «persona de Cirene», la importante colonia griega en la región norteafricana de Cirenaica (actual este de Libia). La ciudad albergaba una comunidad judía numerosa e influyente. En el NT, Simón el Cireneo es obligado a cargar la cruz de Jesús camino al Gólgota (Mateo 27:32; Marcos 15:21; Lucas 23:26), convirtiéndose en figura imborrable del relato de la Pasión. También aparecen cirenenses entre los judíos helenistas que disputaban con Esteban (Hechos 6:9) y entre los primeros misioneros que predicaron a los gentiles en Antioquía (Hechos 11:20; 13:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2957', 'spa', 'Cirene, ciudad griega del norte de África en la actual Libia', 'Lucas señala que entre la multitud en Pentecostés había ''visitantes de Roma, tanto judíos como prosélitos, cretenses y árabes'', así como gente de Cirene (Hechos 2:10). Cirene era una importante colonia griega en el norte de África (la actual Libia), con una población judía considerable. Simón de Cirene cargó la cruz de Jesús (Mateo 27:32); la iglesia en Antioquía incluía creyentes cireneos (Hechos 13:1). La prominencia de la ciudad en la Diáspora la convirtió en una fuente importante de influencia judía helenística en el cristianismo primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2958', 'spa', 'Cirenio, gobernador romano durante el censo (Lucas 2:2)', 'Lucas fecha el nacimiento de Jesús en relación con ''el primer censo que se hizo siendo Cirenio gobernador de Siria'' (Lucas 2:2). Esta nota cronológica ha generado considerable debate histórico, ya que la gobernación de Cirenio se data entre el 6 y el 7 d.C., mientras que el nacimiento de Jesús suele ubicarse antes. Se han propuesto diversas soluciones: una gobernación anterior, un censo previo, o entender ''primer'' como ''antes de'' aquel célebre censo. Sea cual sea la relación histórica precisa, la intención de Lucas es anclar la natividad en la historia romana verificable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2961', 'spa', 'Ejercer señorío o dominio, gobernar, ser amo de; usado de gobernantes, del poder de la muerte, del reinado del pecado y de la soberanía de Cristo.', 'Κυριεύω describe el ejercicio de señorío o autoridad soberana sobre alguien o algo. Jesús lo usa críticamente respecto a los gobernantes gentiles que ''se enseñorean'' de sus súbditos (Lc 22:25), contrastando la dominación mundana con el liderazgo de servicio. Pablo lo aplica teológicamente: la muerte una vez tuvo dominio, pero ya no se enseñorea del Cristo resucitado (Ro 6:9), el pecado no se enseñoreará de los creyentes bajo la gracia (Ro 6:14), y la ley señorea sobre la persona solo mientras vive (Ro 7:1). El verbo conlleva un matiz de control soberano más que de guía suave.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2962', 'spa', 'Señor, amo, señor; dueño — desde un tratamiento de cortesía hasta el título divino para Dios y Cristo', 'Una palabra con un amplio rango de significados que van desde un simple tratamiento de respeto hasta el título supremo de Dios. Puede referirse a Cristo como Señor divino, a un amo humano, a un tratamiento cortés, o al dueño de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2963', 'spa', 'Señorio, dominio, autoridad soberana; tanto el concepto abstracto de poder gobernante como una clase de seres angelicales.', 'Derivado de κύριος (''señor''), este sustantivo tiene tanto un sentido abstracto como uno concreto en el NT. En lo abstracto, denota autoridad soberana o poder de gobierno — el tipo de dominio que pertenece a Dios o que ejercen los gobernantes. En lo concreto, aparece en las jerarquias angelicales paulinas como un rango de seres celestiales: ''tronos, señorios, principados, potestades'' (Col 1:16). En 2 Pe 2:10 y Jud 8, rechazar la κυριότης significa despreciar la autoridad divinamente constituida. Las evidencias multilingues — español señorio, frances autorite, aleman Herrschaft — convergen en el concepto de poder soberano gobernante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2965', 'spa', 'Perro; usado literalmente para perros callejeros carroñeros y figuradamente como termino de desprecio para los moralmente impuros.', 'En el antiguo Cercano Oriente, los perros no eran queridas mascotas domesticas sino carroñeros semisalvajes que vagaban por calles y basureros. Este trasfondo cultural ilumina cada uso neotestamentario. Jesus advierte contra dar las cosas santas a los ''perros'' (Mt 7:6), metafora de lo profano o indigno. En la parabola de Lazaro, los perros lamen las llagas del mendigo — señal de su total indigencia (Lc 16:21). El tajante ''¡Guardaos de los perros!'' de Pablo (Fil 3:2) apunta contra los oponentes judaizantes. Segunda Pedro 2:22 cita el proverbio del perro que vuelve a su vomito, y Apocalipsis 22:15 excluye a los ''perros'' de la ciudad santa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2966', 'spa', 'miembros del cuerpo, extremidades; usado colectivamente para referirse a cadáveres (cuerpos caídos en el desierto)', 'Hebreos recuerda el juicio de Dios sobre la generación del éxodo: «¿Y con quiénes estuvo irritado cuarenta años? ¿No fue con los que pecaron, cuyos cuerpos cayeron en el desierto?» (Hebreos 3:17). El término significa literalmente miembros o extremidades del cuerpo, pero funciona como una manera vívida de decir «cuerpos» o «cadáveres». En el uso clásico incluye brazos y piernas, las partes articuladas del cuerpo. El plural subraya la multitud de cuerpos esparcidos por el desierto, una generación que no logró entrar en el reposo. La imagen es deliberadamente cruda: la rebelión conduce a la muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2967', 'spa', 'Impedir, prevenir o prohibir; bloquear una accion mediante obstruccion o prohibicion autoritativa.', 'Impedir, prevenir o prohibir; bloquear una accion mediante obstruccion o prohibicion autoritativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2968', 'spa', 'Aldea; un asentamiento rural sin murallas, mas pequeno que una ciudad, tipico de la vida campestre en Galilea y Judea.', 'Aldea; un asentamiento rural sin murallas, mas pequeno que una ciudad, tipico de la vida campestre en Galilea y Judea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2969', 'spa', 'pueblos, aldeas con cierto desarrollo urbano; poblaciones intermedias entre aldea y ciudad', 'Marcos describe el inicio del ministerio de Jesús en Galilea: «Vamos a los pueblos vecinos, para que predique también allí» (Marcos 1:38). Este término compuesto designa asentamientos más grandes que simples aldeas pero que no llegan a ser ciudades propiamente dichas: pueblos con mercado o aldeas grandes con algunas características urbanas. Eran centros de población significativos en toda Galilea, comunidades agrícolas con mercados y sinagogas pero sin alcanzar el estatus pleno de ciudad. La estrategia de Jesús consistía en un ministerio itinerante a través de esta red de pueblos, llevando el evangelio a la población más amplia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2970', 'spa', 'desenfreno, orgía; fiesta desenfrenada caracterizada por la embriaguez excesiva y la pérdida de dominio propio', 'Este término describe celebraciones ruidosas y fiestas de borrachera marcadas por el exceso y la pérdida del dominio propio. En contextos religiosos paganos podía referirse a procesiones en honor a Dioniso, pero en general designaba cualquier festejo desenfrenado. Pablo lo incluye sistemáticamente entre las «obras de la carne» (Gálatas 5:21) y las conductas incompatibles con la vida cristiana (Romanos 13:13; 1 Pedro 4:3). La palabra no alude simplemente al consumo social de bebida, sino al abandono moral y al caos propio de las fiestas de borrachera. El uso en plural subraya la participación habitual en este estilo de vida, no incidentes aislados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2971', 'spa', 'mosquito, insecto diminuto; usado en el contraste hiperbólico con el camello', 'Jesús ridiculiza las prioridades farisaicas con una imagen memorable: «¡Guías ciegos, que coláis el mosquito y os tragáis el camello!» (Mateo 23:24). El mosquito representa la criatura más pequeña e insignificante, algo que uno podría filtrar cuidadosamente del agua para evitar la impureza ceremonial. Lo absurdo es que mientras cuelan meticulosamente los insectos diminutos, se tragan camellos enteros, el animal impuro más grande. La hipérbole expone valores invertidos: obsesionarse con minucias mientras se ignoran graves faltas morales. Ambos animales son impuros, pero la desproporción resulta a la vez cómica y condenatoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2972', 'spa', 'Cos, isla del Egeo cerca de Asia Menor; escala en el viaje de Pablo hacia Jerusalén', 'Lucas traza el último viaje de Pablo a Jerusalén con precisión geográfica: «Navegamos directamente a Cos» (Hechos 21:1). Cos (la actual Kos) era una isla importante del Dodecaneso, famosa por su escuela de medicina (la patria de Hipócrates), sus vinos y su producción de seda. La isla constituía una parada natural para pernoctar en la ruta de navegación costera desde Troas hacia Judea. La mención de Lucas refleja el itinerario detallado de un testigo ocular o de un historiador meticuloso. La breve aparición de la isla marca una etapa en el viaje de Pablo hacia su arresto y su eventual llegada a Roma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2973', 'spa', 'Cosam, antepasado de Jesús en la genealogía de Lucas', 'Cosam aparece únicamente en la genealogía de Jesús según Lucas, situado entre Adi y Elmadán en el linaje postexílico. Como ocurre con muchos nombres en esta sección de Lucas 3, los detalles históricos más allá del registro genealógico son desconocidos. El nombre podría derivar de una raíz hebrea, aunque su etimología sigue siendo incierta. Su inclusión en la genealogía subraya la intención de Lucas de trazar una línea completa desde Jesús hasta Adán, documentando cada eslabón de la cadena, incluso aquellos sobre los cuales la historia guarda silencio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2974', 'spa', 'Mudo (incapaz de hablar) o sordo (incapaz de oír); describe una discapacidad sensorial, frecuentemente en el contexto de sanidades milagrosas. Adjetiv', 'Mudo (incapaz de hablar) o sordo (incapaz de oír); describe una discapacidad sensorial, frecuentemente en el contexto de sanidades milagrosas. Adjetivo que abarca dos impedimentos físicos distintos — la incapacidad de hablar y la incapacidad de oír — ambos prominentes en el ministerio sanador de Jesús. En los Evangelios, el endemoniado mudo habla tras ser liberado (Mt 9:32-33), y el hombre sordo con impedimento del habla oye tras el toque de Jesús (Mc 7:32-37). El griego antiguo ya portaba ambos significados, ya que la percepción ''embotada'' podía aplicarse a cualquiera de las dos facultades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2975', 'spa', 'Obtener por suerte, recibir por asignación divina; ser escogido o designado mediante sorteo o reparto providencial.', 'Verbo arraigado en la práctica griega de repartir porciones mediante el sorteo. En el uso clásico significaba obtener lo que a uno le corresponde —tierra, cargo o herencia— por la caída de la suerte. El NT conserva este sentido concreto en Lc 1:9, donde a Zacarías le tocó por suerte quemar incienso, y en Jn 19:24, donde los soldados echan suertes sobre la túnica de Jesús. Pero el vocablo se extiende también al reparto divino: en Hch 1:17 Judas había «obtenido parte» en el ministerio apostólico, y en 2 Pe 1:1 los creyentes han «alcanzado una fe» de igual valor. El español echar suerte refleja fielmente el núcleo del sorteo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2976', 'spa', 'Lázaro; nombre propio llevado por el hermano de María y Marta, y por el mendigo en la parábola de Jesús. Adaptación griega del nombre hebreo Eleazar (', 'Lázaro; nombre propio llevado por el hermano de María y Marta, y por el mendigo en la parábola de Jesús. Adaptación griega del nombre hebreo Eleazar (''Dios ha ayudado''), abreviado coloquialmente a Λάζαρος. Dos figuras distintas llevan este nombre en el Nuevo Testamento. El primero es Lázaro de Betania, hermano de Marta y María, a quien Jesús resucitó de entre los muertos después de cuatro días en la tumba (Jn 11:1-44) — un episodio que se convierte en catalizador de la conspiración contra Jesús. El segundo es el mendigo indigente en la parábola de Jesús sobre el hombre rico y Lázaro (Lc 16:19-31), cuya inversión de fortuna en el más allá enseña sobre la justicia y la compasión. El significado del nombre, ''Dios ha ayudado,'' resuena conmovedoramente en ambas narrativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2977', 'spa', 'En secreto, a escondidas, sin conocimiento ajeno; de manera encubierta para evitar la atención pública.', 'Adverbio que significa «en secreto» o «a escondidas», y describe acciones realizadas sin que otros se enteren. Aparece en contextos que van desde la discreción compasiva hasta la ocultación calculada. José planea repudiar a María λάθρᾳ para no exponerla al escarnio público (Mt 1:19), mientras que Herodes convoca a los magos λάθρᾳ para un interrogatorio encubierto (Mt 2:7). Marta llama a su hermana λάθρᾳ para que la multitud de dolientes no la siga (Jn 11:28), y los magistrados de Filipos intentan liberar a Pablo y Silas λάθρᾳ para evitar un escándalo (Hch 16:37). El español en secreto y el alemán heimlich confirman un sentido único y coherente de acción encubierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2978', 'spa', 'tempestad violenta, torbellino; tormenta furiosa con vientos poderosos, a menudo acompañada de lluvia', 'Esta palabra describe una tempestad violenta y furiosa, de esas que barren la superficie del agua con fuerza destructora, amenazando con volcar embarcaciones y ahogar a sus ocupantes. Los Evangelios la emplean en los relatos donde Jesús calma la tormenta: Marcos 4:37 describe el gran temporal que se levantó en el mar de Galilea, llenando la barca de agua mientras Jesús dormía, y Lucas 8:23 relata el episodio paralelo. 2 Pedro 2:17 usa el término metafóricamente, comparando a los falsos maestros con fuentes sin agua y neblinas empujadas por la tempestad: prometen refrigerio pero no entregan nada, siendo inestables y arrastrados por fuerzas caóticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2980', 'spa', 'Hablar, decir o contar; comunicación verbal general, incluyendo formas pasivas con el sentido de «ser dicho» o «ser hablado».', 'Originalmente con un matiz de habla informal o charla (frente al más formal λέγω), λαλέω se convirtió en el verbo estándar del Nuevo Testamento para hablar y conversar, con 299 apariciones. Describe desde el mudo que finalmente «habló» tras la sanación de Jesús (Mt 9:33) hasta los creyentes llenos del Espíritu hablando en otras lenguas en Pentecostés (Hch 2:4). En sus formas pasivas significa «ser dicho» o «ser hablado», como cuando se promete a María que lo dicho por el Señor se cumplirá (Lc 1:45). El español hablar y el alemán reden reflejan con exactitud el sentido activo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2981', 'spa', 'Habla, modo de hablar, dialecto; la manera de expresarse que revela origen, identidad o mensaje.', 'Sustantivo que abarca tanto el contenido como la forma de hablar. Derivado de λαλέω («hablar»), λαλιά puede significar «habla» en general, un «dialecto» o acento particular que delata el origen regional, o la sustancia de lo que alguien dice. La λαλιά galileana de Pedro lo delata en el patio del sumo sacerdote (Mt 26:73; Mr 14:70): su acento resulta inconfundible. En el Evangelio de Juan, Jesús distingue entre su λαλιά (modo de hablar) y su λόγος (palabra/mensaje), sugiriendo que los oyentes ni siquiera logran procesar su habla, mucho menos captar su enseñanza (Jn 8:43). El español habla y el alemán Rede conservan esta doble dimensión de habla como expresión y habla como dialecto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2983', 'spa', 'Tomar, recibir, obtener o asir; abarca la acción física de agarrar, recibir dones o autoridad, y la captura por fuerza.', 'Pocos verbos griegos poseen un rango tan amplio como λαμβάνω. En su sentido más concreto, describe el simple acto de tomar pan o una copa en las manos —el gesto que Jesús realiza en la Última Cena (Mt 26:26). Pero se extiende sin esfuerzo a recibir dones, salarios, el Espíritu Santo y las promesas divinas. La evidencia multilingüe revela cómo cada lengua recorta este espectro de modo diferente: el coreano usa 받다 («recibir») para la recepción pasiva pero 잡다 («agarrar») cuando hay fuerza, mientras que el suajili alterna entre -pokea («recibir») y -shika («asir»). La amplitud del verbo es en sí misma teológicamente significativa: la misma palabra describe tanto el dar de Dios como el asir de la humanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2984', 'spa', 'Lamec, patriarca en la genealogía de Jesús por la línea de Set', 'Lamec aparece en la genealogía de Lucas como padre de Matusalén y descendiente de Enós. Es el mismo patriarca mencionado en Génesis 5:25-31, donde vivió 777 años y engendró a Noé. El nombre hebreo (לֶמֶךְ) se transliteró al griego como sustantivo propio indeclinable, conservando su forma semítica. Este personaje sirve como eslabón vital en la cadena genealógica que conecta a Jesús con los patriarcas antediluvianos, subrayando la continuidad del plan redentor de Dios desde los orígenes de la humanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2985', 'spa', 'Fuente de luz portátil: una pequeña lámpara de aceite (como en la parábola de las diez vírgenes) o una antorcha o tea más grande.', 'En el mundo antiguo la distinción entre una pequeña lámpara de aceite doméstica y una gran antorcha para exteriores era importante, y λαμπάς abarca ambas. La parábola de las diez vírgenes (Mt 25:1-8) gira en torno a lámparas de aceite —recipientes que deben llenarse y recortarse—, y el hindi emplea el culturalmente resonante «deepak» (दीपक), mientras que el árabe usa «masabiih» (مَصَابِيحَ), ambos denotando claramente lámparas de aceite. Pero cuando los soldados vienen a arrestar a Jesús portando λαμπάδες (Jn 18:3), se trata de antorchas para exteriores: el español distingue «antorcha» de «lámpara». Apocalipsis usa el término para los siete espíritus ardientes ante el trono de Dios (Ap 4:5) y la gran estrella que cae como una antorcha (Ap 8:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2986', 'spa', 'Brillante, resplandeciente, radiante en apariencia; también espléndido, magnífico o lujoso en calidad.', 'Adjetivo cuyo campo semántico se extiende desde la luminosidad física hasta la grandeza social. Cuando describe vestiduras angélicas (Hch 10:30; Ap 15:6) o el río de la vida «brillante como el cristal» (Ap 22:1), la palabra denota resplandor visible — en español «brillante» o «resplandeciente». Pero cuando Santiago advierte contra favorecer al hombre con «ropa espléndida» (Stg 2:2-3), el brillo es metafórico: es el lustre de la riqueza y el estatus social. Apocalipsis 18:14 amplía esto aún más con «cosas espléndidas» perdidas en la caída de Babilonia. Ambos sentidos se solapan —las vestiduras finas pueden brillar literalmente—, pero la evidencia multilingüe muestra que los traductores distinguen consistentemente la radiancia luminosa de la magnificencia costosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2987', 'spa', 'resplandor, fulgor, esplendor (especialmente referido a la luz)', 'Este término designa un brillo intenso o resplandor radiante, utilizado en el griego clásico para referirse a la luminosidad de los cuerpos celestes, los metales pulidos o las armaduras relucientes. En Hechos 26:13, Pablo describe la luz que lo deslumbró camino a Damasco como superior al brillo del sol de mediodía. La palabra conlleva connotaciones de intensidad visual abrumadora y gloria sobrenatural, señalando una manifestación divina que trasciende todo fenómeno luminoso conocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2988', 'spa', 'espléndidamente, con magnificencia, suntuosamente', 'Este adverbio describe un modo de vivir o actuar caracterizado por el lujo, la magnificencia o la ostentación extravagante. En Lucas 16:19, modifica la manera en que el hombre rico banqueteaba cada día: no simplemente comía bien, sino que se entregaba a un consumo fastuoso y ostentoso. El término evoca el estilo de vida de la élite adinerada del mundo grecorromano, donde la exhibición pública de la riqueza funcionaba como un marcador social de estatus y poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2989', 'spa', 'Brillar, resplandecer, irradiar luz; se usa para lámparas, el sol, relámpagos, Cristo transfigurado y los justos en gloria.', 'λάμπω describe la emisión activa de luz, ya sea de una lámpara puesta en un candelero (Mt 5:15), del destello de un relámpago que cruza el cielo (Lc 17:24) o del rostro radiante de Jesús transfigurado brillando como el sol (Mt 17:2). Aparece tanto en contextos literales como teológicamente profundos: los creyentes son llamados a dejar que su luz brille ante los demás (Mt 5:16), y la luz repentina de un ángel llena una celda oscura (Hch 12:7). El español ''brillar'' y ''alumbrar'' captan la cualidad activa y dirigida hacia fuera de este resplandor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2990', 'spa', 'λανθάνω (lanthano) -- pasar inadvertido, estar oculto, ignorar; hacer algo sin ser percibido', 'Lanthano es un verbo que significa ''pasar inadvertido'' o ''permanecer oculto a la percepción,'' encarnando una construcción típicamente griega en la que el sujeto ''escapa a la atención'' de otros mientras realiza una acción expresada mediante un participio suplementario. En el NT aparece en contextos de ocultamiento tanto físico como espiritual: Jesús intenta pasar inadvertido al entrar en una casa pero ''no pudo esconderse'' (Mark 7:24), la mujer sanada se da cuenta de que ''no pasó inadvertida'' (Luke 8:47), y Pedro advierte que a los burladores voluntariamente ''se les escapa'' que Dios creó por su palabra (2 Pet 3:5). El campo semántico abarca el ocultamiento y la falta de percepción consciente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2991', 'spa', 'labrado en roca, tallado en piedra', 'Este adjetivo describe algo cortado o labrado directamente en roca sólida, en particular tumbas excavadas en acantilados o laderas. En Lucas 23:53, caracteriza el sepulcro nuevo donde José de Arimatea depositó el cuerpo de Jesús: una cámara funeraria tallada enteramente en la roca viva, no construida con mampostería. Estos sepulcros excavados en piedra eran lugares de sepultura prestigiosos en la Judea del siglo primero, que requerían un gasto y esfuerzo considerables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2992', 'spa', 'Pueblo: un cuerpo de personas unido por identidad étnica, nacional o religiosa; especialmente Israel como pueblo elegido de Dios.', 'En el griego clásico, λαός podía referirse a soldados, ciudadanos o gente común, pero la Septuaginta lo redujo a un poderoso término teológico: el pueblo de Dios, Israel como comunidad pactual distinta de los ἔθνη (naciones/gentiles). El Nuevo Testamento preserva esta fuerza. Gabriel anuncia que Jesús «salvará a su pueblo de sus pecados» (Mt 1:21), Zacarías bendice a Dios por haber visitado «a su pueblo» (Lc 1:68), y Hebreos extiende el concepto a la comunidad del nuevo pacto (He 4:9). A lo largo de 142 apariciones, λαός retiene esta textura pactual. El español pueblo, el francés peuple y el alemán Volk captan su resonancia comunitaria y política.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2993', 'spa', 'Λαοδίκεια (Laodikeia) -- Laodicea, ciudad próspera de Frigia (Asia Menor), sede de una de las siete iglesias de Apocalipsis', 'Laodikeia es el nombre propio de Laodicea, una próspera ciudad helenística y romana en el valle del Lico en Frigia (actual Turquía occidental), situada cerca de Colosas y Hierápolis. Fundada por el rey seléucida Antíoco II y nombrada en honor a su esposa Laódice, se enriqueció gracias a la banca, la producción de lana negra y una célebre escuela de medicina. Pablo expresa su preocupación por los creyentes laodicenses junto con los de Colosas (Col 2:1; 4:13, 15-16), y en Apocalipsis es la séptima y última iglesia a la que se dirige, reprendida por ser ''tibia, ni fría ni caliente'' (Rev 3:14-22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2994', 'spa', 'laodiceo, habitante o miembro de la iglesia de Laodicea', 'Este adjetivo identifica a personas o cosas asociadas con Laodicea, una ciudad importante del valle del Lico en Asia Menor. En Colosenses 4:16, Pablo hace referencia a una carta que circulaba entre los laodiceos, lo que indica la existencia de comunidades cristianas activas en la región. Laodicea fue posteriormente una de las siete iglesias a las que se dirige el libro de Apocalipsis, conocida por su riqueza material y su fe tibia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2995', 'spa', 'garganta, laringe, gaznate', 'Este término anatómico designa la garganta o laringe, la parte superior de la tráquea empleada en la vocalización. En el griego clásico se refería tanto a la estructura física como, metafóricamente, al habla o al apetito. Pablo cita el Salmo 5:9 en Romanos 3:13, utilizando esta palabra en una vívida metáfora sobre la corrupción humana: «Sepulcro abierto es su garganta». La imagen subraya cómo el habla pecaminosa difunde muerte y destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2996', 'spa', 'Lasea, ciudad costera en Creta', 'Lasea era una ciudad portuaria menor en la costa sur de Creta, cercana a Buenos Puertos. Aparece únicamente en Hechos 27:8 durante el viaje de Pablo hacia Roma, donde el barco se detuvo antes de intentar la peligrosa travesía otoñal hacia el oeste. Su identificación arqueológica sigue siendo incierta, aunque la ubicación general cerca de la moderna Kali Limenes es ampliamente aceptada. El nombre se conserva con ligeras variaciones ortográficas en distintas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2997', 'spa', 'reventar, abrirse violentamente, estallar', 'Este verbo describe una ruptura repentina y violenta, un reventón o estallido. En el uso clásico se aplicaba al crujir de huesos, el crepitar del fuego o el reventar de objetos sometidos a presión. En Hechos 1:18 describe la muerte espantosa de Judas Iscariote, cuyo cuerpo se reventó en el campo comprado con el dinero de su traición. El relato difiere del ahorcamiento narrado en Mateo, pero ambos subrayan el trágico final de Judas y la asociación del campo con el precio de sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2999', 'spa', 'Servicio o culto sagrado, especialmente el deber ritual rendido a Dios; la practica de la adoracion divina.', 'Originalmente designaba el servicio de un trabajador asalariado, pero en el uso judio y cristiano se restringio al culto sagrado o deber liturgico ofrecido a Dios. Pablo cuenta la λατρεία de Israel entre sus grandes privilegios (Ro 9:4). Luego la redefine radicalmente en Ro 12:1: presentar el cuerpo como «sacrificio vivo» es λογικὴ λατρεία, «culto racional». Hebreos emplea el termino para los deberes rituales sacerdotales del tabernaculo (Heb 9:1, 6). La evidencia multilingue se divide entre «culto/adoracion» y «servicio», reflejando el doble enfasis del vocablo en devocion y deber.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3000', 'spa', 'Servir o adorar a Dios con devocion reverente; realizar un servicio sagrado o ministerio religioso.', 'Servir o adorar a Dios con devocion reverente; realizar un servicio sagrado o ministerio religioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3001', 'spa', 'Hortaliza o hierba de huerto; planta cultivada para alimento, a diferencia de la vegetacion silvestre.', 'Λάχανον designa las plantas cultivadas en el huerto —hortalizas y hierbas sembradas intencionalmente para consumo humano—, en contraste con las plantas silvestres que brotan por si solas. Jesus emplea la parabola del grano de mostaza (Mt 13:32; Mr 4:32) para ilustrar como el reino de Dios comienza siendo la semilla mas pequena y, sin embargo, crece hasta superar a todas las hortalizas. En Lc 11:42 los fariseos diezman hasta las hierbas del huerto, y en Ro 14:2 el termino describe la dieta de quienes solo comen legumbres. La palabra evocaba asociaciones cotidianas y humildes: el huerto casero, no la gran cosecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3002', 'spa', 'Lebeo; nombre alternativo o adicional del apóstol también llamado Tadeo o Simón el Zelote', 'Nombre alternativo de uno de los Doce Apóstoles, que aparece en algunas tradiciones manuscritas de Mateo 10:3 y Marcos 3:18. La crítica textual revela una variación compleja: algunos testimonios leen Θαδδαῖος (Tadeo), otros Λεββαῖος, y algunos combinan ambos. En Lucas 6:15 y Hechos 1:13, el mismo individuo figura como «Simón el Zelote» o «Judas [hijo] de Jacobo». La etimología es discutida, posiblemente derivada de la palabra hebrea para «corazón» (leb). Los múltiples nombres reflejan la práctica antigua común de llevar más de un nombre, complicada por la transmisión manuscrita. Las ediciones modernas generalmente prefieren Tadeo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3003', 'spa', 'Legión; gran multitud, originalmente una unidad militar romana de ~5.000 soldados, usada literal y figuradamente para una horda demoníaca.', 'Préstamo latino que pasó al griego por la presencia militar de Roma, legión designa tanto una división formal del ejército romano (unos 5.000 infantes más caballería) como, por extensión, una multitud abrumadora. En los Evangelios aparece de manera memorable como autoidentificación de los espíritus que poseían a un endemoniado: «Mi nombre es Legión, porque somos muchos» (Mc 5:9; Lc 8:30). Jesús también la invoca en Getsemaní, declarando que podría convocar más de doce legiones de ángeles (Mt 26:53). El término transmite tanto poder organizado como numerosidad aterradora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3004', 'spa', 'Decir, hablar, contar; significar, llamar, nombrar — el verbo principal del habla, la declaración y la designación', 'El verbo más común y fundamental para expresar el acto de hablar o comunicar. Abarca desde simples declaraciones hasta órdenes directas y el acto de dar nombre o designar algo o alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3005', 'spa', 'remanente, lo que queda después de que otros son apartados', 'Este sustantivo designa lo que queda después de que una parte ha sido eliminada o destruida: un residuo o remanente sobreviviente. En la teología bíblica posee un peso teológico especial como concepto de los pocos fieles que permanecen tras el juicio. Pablo lo emplea en Romanos 11:5 para describir a los creyentes judíos en Cristo como un remanente escogido por gracia, haciendo eco de los temas proféticos del Antiguo Testamento sobre la preservación divina de un pueblo fiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3006', 'spa', 'liso, llano, parejo', 'Este adjetivo describe superficies lisas al tacto, terrenos llanos o mares en calma: todo aquello que carece de aspereza o irregularidad. En Lucas 3:5, el ministerio de Juan el Bautista se describe utilizando Isaías 40:4, donde los caminos ásperos serán allanados como preparación para la venida del Señor. El término sugiere la eliminación de obstáculos y la creación de un paso libre, con profundo significado espiritual: la remoción de barreras y la preparación de los corazones para la visitación de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3007', 'spa', 'λείπω (leipo) -- carecer, faltar, ser deficiente; estar falto de lo necesario', 'Leipo significa ''carecer'' o ''ser deficiente,'' y aparece en el NT predominantemente en voz medio-pasiva (leipomai) para expresar el estado de quedarse corto o estar en necesidad. Jesús le dice al joven rico ''una cosa te falta'' (Luke 18:22), Pablo instruye a Tito a ''corregir lo que falta'' (Titus 1:5), y Santiago declara que si a alguien le falta sabiduría, que la pida a Dios (Jas 1:5). La palabra posee una cualidad pragmática y diagnóstica: identifica la brecha específica entre la realidad presente y lo que se necesita para completarla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3008', 'spa', 'ministrar, servir; realizar un servicio religioso o público, especialmente en el culto o en funciones sacerdotales', 'Originalmente este verbo designaba el servicio público que un ciudadano prestaba a sus expensas en las ciudades griegas, y con el tiempo pasó a describir el ministerio religioso y el servicio sacerdotal. El Nuevo Testamento lo emplea tanto para la adoración como para el servicio cristiano práctico. Hechos 13:2 describe a profetas y maestros «ministrando al Señor» en Antioquía —probablemente en oración, ayuno y adoración— cuando el Espíritu Santo llamó a Bernabé y a Saulo a la obra misionera. Romanos 15:27 habla de los gentiles sirviendo materialmente a los creyentes judíos, y Hebreos 10:11 describe a los sacerdotes que ministran diariamente en el tabernáculo. El término une el culto litúrgico con el servicio práctico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3009', 'spa', 'λειτουργία (leitourgia) -- servicio público o ministerio realizado para Dios o la comunidad de fe; deber litúrgico, función sacerdotal', 'Enraizada en el concepto griego clásico de servicio público realizado a expensas propias, leitourgia adquiere un profundo significado sagrado en el Nuevo Testamento. Abarca tanto los deberes litúrgicos formales del sacerdocio levítico (Luke 1:23, donde Zacarías completa su servicio en el templo) como el generoso ministerio de los creyentes entre sí (2 Cor 9:12, donde la ayuda económica se convierte en un acto sagrado). Pablo incluso enmarca su propia labor apostólica como una ofrenda sacerdotal (Phil 2:17), mostrando cómo esta palabra tiende un puente entre el ritual del Antiguo Pacto y el servicio de entrega del Nuevo Pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3010', 'spa', 'ministrador, que sirve, litúrgico; relativo al servicio o ministerio sagrado', 'Este adjetivo describe aquello que está relacionado con el servicio o ministerio, especialmente en contextos religiosos. Deriva de λειτουργία (servicio público, liturgia) y designa lo que cumple una función de servicio. En Hebreos 1:14 se aplica a los ángeles, llamados espíritus ministradores enviados para servir a quienes heredarán la salvación, subrayando su papel funcional dentro de los propósitos de Dios. El término enfatiza la acción de servir por encima de cualquier rango o dignidad propia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3011', 'spa', 'Servidor público o ministro; quien sirve en capacidad oficial, ya sea cívica o sagrada.', 'Formado a partir de las raíces griegas para «público» y «obra», λειτουργός designaba originalmente al ciudadano que financiaba obras públicas de su propio peculio, un concepto profundamente cívico. El NT conserva esta amplitud semántica. En Ro 13:6, las autoridades gobernantes son λειτουργοί de Dios en su función civil. Pablo se llama a sí mismo λειτουργός de Cristo Jesús en ministerio sacerdotal a los gentiles (Ro 15:16). Epafrodito es el λειτουργός de Filipos para las necesidades de Pablo (Fil 2:25). Hebreos aplica el término a los ángeles (1:7) y al ministerio sacerdotal superior de Cristo (8:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3013', 'spa', 'escamas, capas delgadas que se desprenden (de los ojos, la piel o superficies)', 'Este sustantivo designa capas finas y laminares que se desprenden o caen, describiendo originalmente escamas de pez, pieles de cebolla, fragmentos metálicos o cualquier formación en placas superpuestas. En Hechos 9:18, unas escamas caen de los ojos de Saulo tras la oración de Ananías, restaurándole la vista. Ya sea literal o metafórica, la imagen transmite la eliminación de la ceguera y la recepción de la iluminación divina, marcando la transformación de perseguidor a apóstol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3014', 'spa', 'Lepra; temida enfermedad cutánea que causaba descamación y desfiguración, haciendo a la persona ritualmente impura bajo la ley mosaica.', 'Λέπρα designa la enfermedad de la piel que convertía a quienes la padecían en marginados del antiguo Israel, no necesariamente la moderna enfermedad de Hansen, sino una categoría más amplia de afecciones cutáneas graves y visibles que producían descamación (la raíz λεπίς significa «escama»). Sanar a un leproso fue una de las señales más impactantes de la autoridad mesiánica de Jesús: tocó al intocable y lo declaró limpio (Mt 8:3; Mc 1:42; Lc 5:12-13). La enfermedad tenía un enorme peso social y religioso, pues la ley levítica exigía separación de la comunidad hasta que un sacerdote certificara la restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3015', 'spa', 'Leproso; persona afligida por una grave enfermedad cutánea que la hacía ritualmente impura bajo la ley mosaica.', 'Adjetivo que significa «leproso», usado sustantivamente en el Nuevo Testamento para designar a una persona que padecía una grave enfermedad de la piel que la convertía en ritualmente impura y socialmente marginada bajo la ley mosaica. La disposición de Jesús a tocar y sanar leprosos fue uno de sus actos más radicales, desafiando directamente las barreras de pureza. La curación de un leproso es el primer milagro de sanidad en la secuencia de Mateo tras el Sermón del Monte (Mt 8:2-4), y «los leprosos son limpiados» aparece en el propio resumen que Jesús hace de sus credenciales mesiánicas ante Juan el Bautista (Mt 11:5; Lc 7:22). Simón el Leproso hospedó a Jesús en Betania (Mt 26:6; Mc 14:3). El español «leproso» y el francés «lépreux» derivan de la misma raíz griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3016', 'spa', 'leptón; la moneda griega de cobre más pequeña, equivalente a aproximadamente 1/128 de un denario', 'El leptón era la moneda más pequeña y de menor valor en circulación, equivalente a la mitad de un cuadrante romano (y se necesitaban 64 cuadrantes para igualar un denario, el jornal de un día). Su nombre proviene del griego que significa «delgado» o «fino», describiendo tanto su delgadez física como su valor mínimo. Jesús señala esta moneda al enseñar sobre la ofrenda de la viuda: ella dio dos lepta —todo lo que tenía— mientras los ricos daban de lo que les sobraba (Marcos 12:42; Lucas 21:2). Lucas 12:59 lo usa proverbialmente: «no saldrás de allí hasta que hayas pagado el último leptón», recalcando el pago completo hasta la más mínima fracción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3017', 'spa', 'Leví, nombre propio hebreo del hijo del patriarca Jacob y de dos ancestros de Jesús en la genealogía de Lucas.', 'Leví (en hebreo לֵוִי, «unido» o «adherido») aparece en el NT principalmente como el patriarca cuyos descendientes conformaron la tribu sacerdotal de Israel. Hebreos 7:5 y 7:9 invocan a Leví en el argumento de que el sacerdocio de Melquisedec supera al orden levítico: el propio Leví, aún «en los lomos de Abraham», pagó diezmos a Melquisedec. Apocalipsis 7:7 incluye a Leví entre las doce tribus selladas en los tiempos finales. La genealogía de Lucas menciona a dos hombres por lo demás desconocidos llamados Leví en la ascendencia de Jesús (Lc 3:24, 29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3018', 'spa', 'Leví; nombre propio hebreo del patriarca y del discípulo llamado por Jesús', 'Este nombre hebreo (que significa «unido» o «vinculado») identifica a varias figuras bíblicas. El más destacado es Leví, tercer hijo de Jacob y ancestro de la tribu sacerdotal. En los Evangelios designa al recaudador de impuestos a quien Jesús llamó al discipulado. Marcos 2:14 y los pasajes paralelos de Lucas 5:27, 29 lo nombran «Leví hijo de Alfeo», mientras que Mateo 9:9 llama a la misma persona «Mateo». Esto sugiere que Leví era su nombre de nacimiento y Mateo su nombre apostólico, o bien que distintas tradiciones evangélicas tempranas conservaron nombres diferentes para el mismo individuo. En cualquier caso, el llamamiento de un recaudador de impuestos escandalizó al establishment religioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3019', 'spa', 'Levita; miembro de la tribu de Leví que servía como asistente en el culto del templo', 'Los levitas eran miembros de la tribu de Leví que no descendían de Aarón y cumplían diversas funciones en el templo: músicos, porteros, asistentes de los sacerdotes y maestros de la Ley. No recibieron herencia territorial, sino que vivían en ciudades levíticas y se sostenían con los diezmos. En el Nuevo Testamento aparecen tres veces. Juan 1:19 identifica a los enviados a interrogar a Juan el Bautista como sacerdotes y levitas, representantes de la autoridad religiosa oficial. Lucas 10:32 presenta a un levita en la parábola del buen samaritano que, igual que el sacerdote, pasa de largo ante el hombre herido. Hechos 4:36 presenta a Bernabé como levita originario de Chipre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3020', 'spa', 'levítico, perteneciente a la tribu o al sacerdocio de Leví', 'Este adjetivo designa lo que pertenece o se relaciona con los levitas, la tribu sacerdotal descendiente de Leví. En Hebreos 7:11 se refiere específicamente al sacerdocio levítico establecido bajo la ley mosaica. El autor de Hebreos emplea este término al argumentar que el antiguo sacerdocio era imperfecto y necesitaba ser reemplazado por el sacerdocio superior de Cristo, según el orden de Melquisedec. De este modo, lo levítico representa el sistema ceremonial superado por la nueva alianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3022', 'spa', 'Blanco — el color de la pureza, la gloria y el resplandor celestial, aplicado a vestiduras, cabellos, caballos y la cosecha.', 'Blanco — el color de la pureza, la gloria y el resplandor celestial, aplicado a vestiduras, cabellos, caballos y la cosecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3023', 'spa', 'León; gran felino depredador usado literal y figuradamente para expresar poder feroz, peligro o majestad real.', 'Designa al león, el gran felino depredador que en el mundo antiguo simbolizaba tanto una ferocidad aterradora como la majestad real. En el Nuevo Testamento, λέων cumple una doble función figurativa. Primera de Pedro 5:8 advierte que «vuestro adversario el diablo anda rugiendo como león», presentándolo como imagen de amenaza depredadora. Sin embargo, Apocalipsis 5:5 aclama a Cristo como «el León de la tribu de Judá», evocando Génesis 49:9 y el poder mesiánico regio. Pablo afirma que Dios lo «libró de la boca del león» (2 Ti 4:17), y Hebreos 11:33 recuerda a los fieles que «taparon bocas de leones», aludiendo a Daniel. El español «león» y el francés «lion» conservan estos matices regios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3024', 'spa', 'olvido, estado de haber olvidado; pérdida de memoria espiritual', 'Este sustantivo denota el estado de haber olvidado o la condición de caer en el olvido. En el griego clásico personificaba el olvido y daba nombre a un río mítico del Hades cuyas aguas causaban la pérdida de memoria. En 2 Pedro 1:9 describe la ceguera espiritual de quienes carecen de virtudes cristianas: han olvidado la purificación de sus pecados anteriores. No se trata de un simple descuido, sino de una amnesia espiritual peligrosa respecto a la propia identidad redimida en Cristo.');